// GENERATED by scripts/sync-guidance.mjs from every skill folder under server/guidance/ (each holds a
// SKILL.md). Do not edit.
// Shipped as strings so it works in the tsc build and in the esbuild panel bundle.
//   SKILL_TEXT   folder -> relative path -> file text (CRLF normalised to LF)
//   MCP_SKILLS   the Skills extension manifest per skill, sorted by skill name: parsed frontmatter and
//                per file sha256 (lowercase hex of the UTF-8 bytes) and size (UTF-8 bytes), SKILL.md first
//   GUIDANCE_FILES / CAPTIONS_GUIDANCE_FILES  the motion-director and captions entries of SKILL_TEXT

export interface McpSkillFile {
  path: string;
  sha256: string;
  size: number;
}

export interface McpSkillManifest {
  /** Folder under server/guidance/. */
  dir: string;
  /** The frontmatter name; the skill is served at skill://<name>/. */
  name: string;
  frontmatter: { name: string; description: string; [key: string]: unknown };
  files: McpSkillFile[];
}

export const SKILL_TEXT: Record<string, Record<string, string>> = {
  "ae-extendscript": {
    "SKILL.md": "---\nname: ae-extendscript\ndescription: \"How to write ExtendScript that the chroma-ae MCP will accept and run safely in After Effects: code for ae_run_jsx and for saved skills run by ae_skill_run. Covers ES3 syntax limits (no let, const, arrow functions, template strings, class, for...of, chained ternaries; no native JSON), how the code is wrapped and what it returns, the mutates and expect parameters, undo groups, read-back after a write, stale frames from saveFrameToPng, app.executeCommand, timeouts, the safety lint (what it refuses and which tool to use instead) and when to use a dedicated tool instead. Load before calling ae_run_jsx or ae_skill_save, when a script is refused as not ES3 or by the safety lint, when ExtendScript misbehaves silently, or when asked to script After Effects, run JSX or automate something no dedicated tool covers.\"\nmetadata:\n  version: \"1.0.0\"\n---\n\n# ExtendScript for ae_run_jsx\n\n`ae_run_jsx` runs your code inside After Effects. Use it only when no dedicated tool does the job.\nThe same rules apply to the steps of a saved skill (`ae_skill_save`, `ae_skill_run`): they get the\nsame ES3 check and the same safety lint. Each step is also a function body. It sees `args` (the run's\narguments), `prev` (what the previous step returned) and `results`; all steps run in one evalScript,\nso a writing skill is one undo step. Write steps that take what varies from `args`.\n\n## Find a dedicated tool first\n\nA dedicated tool validates its input, takes a checkpoint, reads the result back and returns a\nreceipt. Your script gets the same checkpoint and receipt when `mutates: true`, but nothing checks\nwhat the code does.\n\n- The server lists 34 everyday tools by default (the core toolset) plus `ae_search_tools`,\n  `ae_get_tool_schema` and `ae_invoke_tool`. The rest (about 150 more) are reached through those.\n- `ae_search_tools { query }` finds the rest (keywords, or `pattern` for a name fragment such as\n  `^ae_track`). `ae_get_tool_schema { name }` gives the full schema. `ae_invoke_tool { name, arguments }`\n  runs any tool; put its arguments under `arguments`.\n- Search and schema calls never touch After Effects, so they answer even while AE is busy.\n- HTTP clients can ask for every tool in the list with the header `X-Chroma-Toolset: full`. The\n  stdio relay does the same with `CHROMA_AE_MCP_TOOLSET=full`. Core is the default for everyone.\n- Core tools you will want before reaching for a script: `ae_status`, `ae_get_project`, `ae_get_comp`,\n  `ae_comp_tree`, `ae_find_layers`, `ae_get_layer_props` (`meta: true` shows what a property accepts),\n  `ae_get_keyframes`, `ae_set_property`, `ae_batch_set`, `ae_set_text`, `ae_create_layer`,\n  `ae_create_comp`, `ae_layer_ops` (parent, reorder, duplicate, delete, trim, rename), `ae_add_effect`,\n  `ae_set_effect`, `ae_import_footage`, `ae_save`, `ae_snapshot_frame`.\n- Check `ae_skill_list` (reached through `ae_search_tools`) too: the user may already have a saved\n  skill for the job.\n\n## The tool\n\n`ae_run_jsx { code, mutates, label, expect? }`. It also takes `idempotency_key`, as every write tool does\n(a resend with the same key and arguments returns the first answer instead of running again).\n\n| Field | Rule |\n|---|---|\n| `code` | The body of a function. Write `return <value>` to send a result. Do not write `function () {}` around it. |\n| `mutates` | Required, no default. `true` if the script changes anything in the project. |\n| `label` | Required. Names the undo step in AE and the entry in the panel log. |\n| `expect` | Required when `mutates` is true: `{ project_path, comp_id? }`. Copy `project_path` exactly from `ae_status` (it has a marker in place of a path for a project never saved; pass that unchanged). If AE has something else open the call is refused with `kind: \"guard\"` and nothing runs. |\n\nThe server wraps `code` as `(function(){ <code> \\n})()` evaluated in the panel's scope, so a\n`return` works and line numbers in errors match your `code`. Variables you declare with `var` stay\ninside; an undeclared name becomes a global and leaks into the next call. Always declare with `var`.\n\n## Return values\n\nThere is no native `JSON` in ExtendScript, so do not call `JSON.stringify`. Return plain data and the\nhost converts it:\n\n- Numbers, strings, booleans, arrays and plain objects (`{ a: 1 }`) come back as they are.\n- An After Effects object (a layer, a property, a comp) comes back as a short tag such as\n  `[Layer \"Title\" #12]`, not its contents. Copy out the fields you need.\n- No `return`, or `return null`: the result is `{ returned: null, note: ... }`. That is not a failure.\n  Anything the script changed is applied. Read state back; do not run it again.\n- Output is bounded: lists at 500 entries (the result then says `truncated: true`), strings at 20,000\n  characters. Return less.\n- If you need a string of JSON, `__chromaAe.stringify(value)` exists in the host (it is the panel's\n  own serialiser). Prefer returning the object.\n- Read-only result: `{ op_id, result }`. Mutating result: `{ op_id, applied: true, result, checkpoint,\n  receipt, user_changed? }`. Keep the `op_id`: `ae_skill_save { from_op_ids }` can turn a script that\n  worked into a reusable skill (only if the user asks).\n\n## ES3 only\n\nExtendScript is ECMAScript 3. The server checks the syntax it can see before After Effects is called\nand refuses the call, with the line number, for `let`, `const`, `class`, arrow functions, template\nstrings, `for...of` and chained ternaries. Nothing runs. The other rules below are not checked: break\nthem and the script fails inside After Effects, or quietly does the wrong thing.\n\n- Use `var` and `function`. No `let`, `const`, `class`, arrow functions (`=>`), template strings\n  (backticks) or `for (x of y)`.\n- No `forEach`, `map`, `filter`, `reduce` or `Array.prototype.indexOf`. The host does not polyfill\n  them (`core.jsx` has none). Write a `for` loop with an index. (`String.prototype.indexOf` is ES3\n  and fine.)\n- **No chained ternaries.** `a ? b : c ? d : e` parses as `(a ? b : c) ? d : e`, so the logic is\n  silently wrong. The server refuses it. Use `if / else`.\n- Do not use ES3 reserved words (`default`, `delete`, `class`, `enum`, `export` and the like) as\n  variable names or unquoted object keys. Quote the key: `{ \"default\": 1 }`.\n- Precaution, not measured: keep the code ASCII (use `\\u00e9`-style escapes in strings).\n- `property(name)` returns `null` for a missing property rather than throwing. Test for `null`.\n- Do not hold a `Property` across `addProperty`, `remove()` or `moveTo`. References to siblings go\n  stale (\"Object is invalid\"). Look the property up again by index or match name after each of those.\n- Effect parameters: address by match name. Section headers share names with parameters, so\n  `property(\"Transform\")` on an effect can return the header, not a value.\n- A 2D layer still has three-dimensional Position, Scale and Anchor Point. Setting Scale to\n  `[100, 75]` reads back as `[100, 75, 100]`. Compare only the dimensions you set.\n- Do not run long synchronous loops. They freeze After Effects' UI. The default wait for one call is\n  120 seconds, and `ae_run_jsx` has no parameter to extend it.\n\n## Undo, read-back and receipts\n\n- **One undo group per call, opened and closed by the server** (`withUndo`). Do not call\n  `app.beginUndoGroup` or `app.endUndoGroup` yourself. A group begun in one call and ended in another\n  is discarded by AE. One Ctrl+Z in AE removes the whole call.\n- **Do not verify in the same script that wrote.** A read in the same evalScript as the write returns\n  stale cached values. With `mutates: true` the server reads before and after in separate calls and\n  returns `receipt` (what differs). For your own checks, make a second `ae_run_jsx` call with\n  `mutates: false`, or use `ae_get_layer_props`.\n- **Before a mutating call**, with automatic checkpoints on (the default, for project files up to\n  250 MB; `ae_auto_checkpoint` changes it), the server copies the saved `.aep` to\n  `<projectdir>/_mcp_checkpoints/` (the last save, not unsaved work:\n  `checkpoint.unsaved_changes_not_included` says so). `checkpoint` in the result says whether it was\n  made or skipped, and why.\n- A script that throws part-way has already run its earlier statements inside the undo group. A\n  mutating failure normally reports `outcome: \"unknown\"`; read the state, then decide. Do not resend.\n- Not everything has an undo step: saves, project open and close, renders and font replacement do not.\n\n## Things that do not work through CEP\n\n- `app.executeCommand` does nothing for most commands, silently. Use the DOM: `comp.duplicate()`,\n  `layer.duplicate()`, `layer.remove()`. (Window-menu commands were measured to toggle panels on\n  AE 26.0, but they toggle, so check the state first. Do not rely on it for anything else.)\n- `saveFrameToPng` writes asynchronously and can report success with a cached frame from an earlier\n  render. Do not call it in `ae_run_jsx` and read the file at once. Use `ae_snapshot_frame`: the server\n  waits for the PNG to be non-empty and stable, checks its modified time is newer than the request,\n  retries a stale one once with a +0.001 s nudge, and reports `stale_frame` if still stale. If you must\n  render in your own code, check the file is non-empty and newer than your request and retry once.\n- Custom-data effect parameters (such as Colorama's Output Cycle) cannot be read or set by script.\n\n## Never abort, never loop\n\n- Do not give up on a slow `ae_run_jsx` and send it again. The server never aborts an evalScript,\n  because that wedges the ExtendScript bridge until AE restarts. Calls queue and wait.\n- If the 120 s limit passes, the call returns `kind: \"timeout\"`. For a mutating call: `outcome:\n  \"unknown\"`, the op is quarantined, and every other write is refused until you inspect the state with\n  read tools and call `ae_acknowledge { op_id, note }`. The script may still be running in AE.\n- If AE is busy (a popup, someone else's script, a render) a call is refused at once with\n  `kind: \"queued\"` and `actual.busy`, before anything is sent. Read the popups with `ae_dialogs`,\n  call `ae_status` (it answers at once), and wait about 30 s. Do not retry in a loop.\n- Calls wait their turn in one queue (reads and writes alike) for up to 600 s, then are dropped with\n  `kind: \"queued\"`: nothing ran.\n\n## The safety lint\n\nBefore ES3 is checked, a static lint reads the code (with comments, strings and regex literals blanked,\nso `\"alert\"` in a string does not trigger it). A hit refuses the whole call, nothing runs, and the\nmessage names the line, the member and the tool to use instead.\n\n| Refused | Use instead |\n|---|---|\n| `system.callSystem`, `File.execute`, sockets, `.queueInAME` | nothing: no outside programs |\n| `$.evalFile`, `#include`, `//@include` | `ae_skill_run` (a saved skill's steps) |\n| `$.sleep` | nothing: it blocks the bridge |\n| `alert`, `confirm`, `prompt`, `Window.alert` / `confirm` / `prompt`, `File.openDialog`, `saveDialog`, `Folder.selectDialog`, `.openDlg`, `.saveDlg`, `.selectDlg`, `.saveWithDialog`, `.importFileWithDialog` | `ae_ask_user` (questions), `ae_import_footage` (import) |\n| `ScriptUI`, `new Window` | nothing: no windows inside After Effects |\n| `app.beginSuppressDialogs` | `ae_dialogs`. Popups are read and answered, never hidden. |\n| `app.quit`, `app.restart`, `app.scheduleTask`, `app.watchFolder`, `app.exitAfterLaunchAndEval`, `deletePref` | nothing |\n| `app.newProject`, `app.open`, `app.openFast`, `project.close` | `ae_project_session` |\n| `project.save()` (also via a variable holding `app.project`) | `ae_save` (`save_as: { path }` for another file) |\n| `renderQueue.render`, `pauseRendering`, `stopRendering`, `.onStatusChanged` | `ae_render_queue_render` or `ae_aerender_start` |\n| `app.purge` | `ae_memory_purge` |\n| `File` or `Folder` `remove`, `rename`, `copy`, `create`, `write`, `writeln`, or `open` for writing (also `item.file.remove()`) | nothing: tools write their own files |\n| Team Project methods | nothing |\n\n- With `mutates: false` it also refuses writes: `setValue`, `setValueAtTime`, `addProperty`, `addKey`,\n  `removeKey`, `remove`, `duplicate`, `moveTo`, `layers.add`, `items.add`, `addSolid`, `addText`,\n  `addComp`, `applyPreset`, `replaceSource`, `importFile` and similar. Set `mutates: true` and `expect`.\n- `File.open` with a literal `\"r\"` mode (or no argument) is allowed, for reading. A mode that is not a\n  string literal is refused because it cannot be checked.\n- **It is a guard rail, not a sandbox.** `eval()` of a built string, `obj[\"callSystem\"]`, aliasing a\n  method (`var f = system.callSystem`) and files reached through a chain it cannot follow all get past\n  it. Do not try. You remain responsible for what the code does, and the user's rules (no outside\n  programs, no files written, no dialogs, no suppressed popups) apply whether or not the lint sees it.\n- Do not edit the code to dodge a refusal. If the lint names a tool, use the tool. If it says \"nothing\",\n  tell the user that this MCP does not do it.\n\n## Examples\n\nA read. It changes nothing, so `mutates` is false and `expect` is not needed.\n\n```\nae_run_jsx {\n  \"label\": \"Count layers per comp\",\n  \"mutates\": false,\n  \"code\": \"var out = [];\\nfor (var i = 1; i <= app.project.numItems; i++) {\\n  var it = app.project.item(i);\\n  if (it instanceof CompItem) out.push({ id: it.id, name: it.name, layers: it.numLayers });\\n}\\nreturn out;\"\n}\n```\n\nA guarded write. `project_path` comes from `ae_status`; `comp_id` makes the receipt cover that comp.\n\n```\nae_run_jsx {\n  \"label\": \"Dim background layers to 40%\",\n  \"mutates\": true,\n  \"expect\": { \"project_path\": \"D:/jobs/promo/promo.aep\", \"comp_id\": 7 },\n  \"idempotency_key\": \"dim-bg-comp7-v1\",\n  \"code\": \"var comp = app.project.itemByID(7);\\nif (!comp || !(comp instanceof CompItem)) { throw new Error('comp 7 not found'); }\\nvar changed = 0;\\nfor (var i = 1; i <= comp.numLayers; i++) {\\n  var layer = comp.layer(i);\\n  if (layer.name.indexOf('BG') === 0) {\\n    layer.property('Transform').property('Opacity').setValue(40);\\n    changed++;\\n  }\\n}\\nreturn { changed: changed };\"\n}\n```\n\nThen, in a separate call, read back what you care about (`ae_get_layer_props`, or a second\n`ae_run_jsx` with `mutates: false`). The `receipt` in the write result already lists what differs.\n\n## Checklist before sending\n\n1. Is there a dedicated tool? (`ae_search_tools`.)\n2. `var` and `function` only, loops not iterators, `if / else` not chained ternaries.\n3. `return` the data you need, as plain objects.\n4. `mutates: true` plus `expect` if anything changes; a `label` the user will recognise in Edit > Undo.\n5. No undo group, no dialog, no file, no save, no render call in the code.\n6. One short call. Verify in a second call. Never resend after a timeout or an `unknown` outcome.\n",
  },
  "ae-fonts": {
    "SKILL.md": "---\nname: ae-fonts\ndescription: \"Find, check and replace fonts in After Effects with the chroma-ae MCP (ae_fonts), and deal with the font warnings. Load for: missing font, font substitution, substituted font, replace font, swap a font project-wide, which fonts does this project use, is this font installed, does the font have the glyphs (Turkish, Cyrillic, Arabic), Unknown BIB Error, cannot access font, ATM Parse Error, CoolType, Adobe Fonts not syncing, duplicate or damaged fonts, a popup that blocks scripts after a font change, ae_busy with a font popup.\"\nmetadata:\n  version: \"1.0.0\"\n---\n\n# Fonts in After Effects\n\nEverything here is done with the `ae_fonts` tool, plus `ae_dialogs` and `ae_dialog_respond` for the\nfont warnings. Fonts are a project read first, a write last: find out what the project uses, check\nwhat is installed, then change.\n\n## Reaching the tools\n\n`ae_dialogs` and `ae_dialog_respond` are core tools: always listed. `ae_fonts` is **not** core. It sits\nin the `text` group, so on the default (core) toolset reach it through the three meta-tools:\n\n- `ae_search_tools { query: \"fonts\" }` (or `group: \"text\"`) to find it.\n- `ae_get_tool_schema { name: \"ae_fonts\" }` for the full schema and safety text. Read it before first use.\n- `ae_invoke_tool { name: \"ae_fonts\", arguments: { ... } }` to call it. Everything below goes under `arguments`.\n\nIf the full list is loaded (HTTP header `X-Chroma-Toolset: full`, or `CHROMA_AE_MCP_TOOLSET=full` for\nthe relay) call `ae_fonts` directly. `ae_search_tools` and `ae_get_tool_schema` never touch After\nEffects, so they work even while AE is blocked by a popup. `ae_invoke_tool` does not: it is refused\nwhile AE is rendering and answers \"busy\" while a popup holds AE.\n\nOther tools used here: core `ae_status`, `ae_get_project`, `ae_save`, `ae_set_text`, `ae_find_layers`;\nreached the same way as `ae_fonts`: `ae_auto_checkpoint`, `ae_checkpoint_revert` (group `safety`),\n`ae_brief` (group `review`), `ae_collect_relink` (group `delivery`).\n\n## ae_fonts actions\n\n`action` is one of `in_use` (the default), `search`, `check`, `replace`, `check_files`. All except a\nreal `replace` are read-only. Needs AE 24 or later (`app.fonts`); `replace` needs 24.5; glyph checks\nneed 25.1. On an older AE the result says so (`available: false` with a `reason`) instead of failing.\n\n### in_use: what the project uses\n\nParameters: `comp_id` (only that comp's text layers; default the whole project), `missing_only`\n(true: list only fonts known to be missing or substituted).\n\nResult: `fonts[]`, one per PostScript name, each with `font` (the PostScript name), `family`, `style`,\n`location`, `missing` (true, false, or null when AE could not say), `uses` and `layers[]` (comp_id,\ncomp, layer_index, layer, and `key` for a keyframe of animated source text). Also `missing[]`,\n`missing_known` (false when any font's state is unknown), `text_layers`, `partial`, `truncated` and\n`skipped_layers` (text layers that could not be fully read, each counted once).\n\nCheck `missing_known` before saying \"no fonts are missing\". With `missing_only`, fonts whose state is\nunknown are left out and counted in `unknown_state`, with a `note`: they may still be missing.\n\n### search: what is installed\n\nParameters: `query` (matches PostScript, family, style or full name, or their native names; case,\nspaces and dashes ignored), `family` (contains), `style` (contains, such as \"bold\"), `writing_script`\n(roman, cyrillic, greek, arabic, hebrew, japanese, chinese_simplified, ...), `variable_only`,\n`adobe_only`, `page` (from 1), `page_size` (default 25, at most 100).\n\nResult: `fonts[]` with names, location, Adobe Fonts flag and variable axes; `total_matches`,\n`has_more`, `scanned`, `scan_truncated`, `font_ids_session_only: true` (a `fontID` is valid for this\nAE session only; never store it). The server walks the whole font list in short steps, up to a\nminute. If `scan_truncated` is true a font that is not listed may still be installed: narrow the\nsearch, or confirm one name with `check`. Do not conclude \"not installed\" from a truncated scan.\n\n`writing_script` says what the font supports in general. Whether it has the letters of a given\nstring is a glyph question: use `check` with `text`.\n\n### check: does this font exist, is it substituted, does it cover this text\n\nParameters: `fonts` (required, 1 to 50; each a PostScript name string such as `\"Arial-BoldMT\"`, or\n`{ family, style }`), `text` (the real string to be shown, up to 20000 characters).\n\nResult: `checked[]` per font with `exists`, `is_substitute`, `duplicates`, `candidates` (near matches\nfor a font that does not exist), `other_fonts_with_same_dict` where AE gives it, `variable` axes for a\nvariable font and, with `text`, `glyphs` (`supported`, `missing` characters, `suggested_default`:\nAE's default font for the script of what is missing). Also `project_missing_or_substituted` (AE's own\nlist) and a `problems` count: fonts that do not exist, are substituted, or lack glyphs.\n\nAlways pass the real text when the font is for a language with special letters (for example a\nTurkish caption). A font can exist and still draw boxes for some characters.\n\n### replace: swap one font for another, project-wide\n\nParameters: `from` and `to` (both required; PostScript name or `{ family, style }`), `dry_run`\n(default **true**), `no_font_locking` (default false), `expect` (required when `dry_run` is false:\n`{ project_path, comp_id? }`, with `project_path` copied exactly from `ae_status`: the open .aep's\nabsolute path, or its marker for a project never saved).\n\n`from` may be a font that is missing: the project's own used-font list is searched for it, not the\ninstalled list. `to` must be installed and must not itself be substituted (`font_not_found` or\n`font_substituted` otherwise).\n\nDry run (the default) changes nothing. It returns `from_used`, `affected_layers`, `uses`, `layers`\n(where the old font is used), `glyphs` (layers whose text the new font cannot draw, with the missing\ncharacters) and `notes`. If `from_used` is false there is nothing to replace.\n\nReal run (`dry_run: false`, with `expect`):\n1. It is **not undoable**: Ctrl+Z does not restore it. The server makes a checkpoint first and\n   refuses (`error: \"checkpoint_required\"`) if none can be made, or if the project has unsaved\n   changes, because a checkpoint copies the saved .aep. Run `ae_save`, and turn automatic\n   checkpoints on with `ae_auto_checkpoint`, then try again.\n2. It calls AE's `Project.replaceFont`, then reads the project's used fonts back and compares: the\n   old font must be gone, the new one present and not substituted, and every place that used the old\n   font must now use the new one. A failed check comes back as a mismatch on the result.\n3. To undo, restore from the checkpoint with `ae_checkpoint_revert` (this loses edits made since).\n\n`no_font_locking: true` stops AE locking glyphs, so missing glyphs can no longer be detected; leave\nit off unless the user asks. In text with mixed fonts, only the ranges that used the old font change.\nThe check runs on the layer's whole text, so a mixed-font layer can list characters the replaced\nrange does not contain.\n\n### check_files: are the font files themselves sound\n\nNo parameters. The host lists every installed font with its file path; the server then checks each\nfile on disk (about 2 s for 800 fonts). Result: `fonts`, `files`, `adobe_fonts`, `problem_fonts`,\n`problem_counts`, `problems[]` (names, `location`, `problem`, `detail`; at most 200), `without_file`,\n`scan_truncated`, `seconds` and a `note` with the fix steps.\n\n`problem` is one of `no_location`, `missing` (file deleted, moved, or on a drive not connected),\n`not_a_file`, `empty` (0 bytes), `unreadable`, `not_a_font` (a .ttf, .otf, .ttc or .otc file whose\nfirst bytes are not a font header; not tested for Adobe Fonts files). Fonts with no file at all are\nlisted under `without_file` and are normal: named instances of a variable font and Windows bitmap\n.fon fonts. They are not problems.\n\n## Order of work\n\n1. `in_use` (add `comp_id` to narrow it). Note `missing`, `missing_known`, `skipped_layers`.\n2. `check` the fonts the brief or the user wants (`ae_brief` holds the brief's fonts), with `text`\n   when the copy has special characters.\n3. `search` for an installed stand-in when a font is missing: same family first, then by `style`,\n   then by `writing_script`. Use `adobe_only` to see which fonts are Adobe Fonts.\n4. `replace` with `dry_run` true. Read `affected_layers` and `glyphs`. Show the user a font that\n   lacks glyphs for their text before going on.\n5. `ae_save`, then `replace` with `dry_run: false` and `expect`.\n6. Read back in a separate call: `in_use` again (or `ae_find_layers` and a snapshot for a visual\n   check). Do not trust the write's own result as the only evidence.\n7. `check_files` only when the BIB warnings appear (below), or before a delivery on a new machine.\n\nSetting fonts on new text: `ae_set_text` (and caption tools) look the font up first on AE 24+ and\nrefuse an unknown or substituted font with near matches. Do not pass `allow_substitute: true` just to\nget past that refusal: it writes a name AE will then replace with a fallback.\n\n## How AE substitutes\n\nWhen a project asks for a font that is not installed, AE keeps the font's name in the text but draws\nwith a fallback. `in_use` shows it as `missing: true`. A substituted `from` font can still be\nreplaced, because `replace` finds it by what the project uses. Match fonts by PostScript name\n(`Arial-BoldMT`), not by display name: family and style names differ by language and foundry, and\n`{ family, style }` is matched with case, spaces and dashes ignored, which can match more than one\nfile. If `check` reports `duplicates` above 0, two installed fonts answer to the same name: say so to\nthe user before choosing.\n\n## Unknown BIB Error. cannot access font / ATM Parse Error\n\nAE can open a popup, \"Unknown BIB Error. cannot access font\", or an \"ATM Parse Error\". They come from\nCoolType, Adobe's font engine, and appear:\n- at the first full font load in a session (the first time something reads the whole font list,\n  for example a font search or a font scan), and\n- again after any font is installed, removed or changed while AE is open.\n\nThe popup **names no font**. Known causes, none of which this server can see directly:\n- the same font installed twice with different files (for example a per-user and a system copy);\n- a font Windows cannot tell from its siblings: same family, weight and italic flags;\n- a second copy of a font AE ships itself, such as Adobe Clean or Adobe Clean UX, installed by a\n  font manager;\n- damaged font files;\n- Adobe Fonts activated while Creative Cloud is not running.\n\n### What the server does with the popup\n\nThe popup blocks scripts: until it is answered, AE-touching tools wait, or fail with \"After Effects\nis busy: a popup is open ...\" and tell you to read `ae_dialogs`. The panel's watcher also reads new\npopups. A one-button OK popup raised by one of our own operations is pressed at once and reported on\nthe next tool result under `popups`; anything else is put to the user in the panel (and in the\nclient too, for a client on an older MCP revision that declared elicitation). Popups are never\nsuppressed.\n\nWhat you do:\n1. Do not retry in a loop. Call `ae_status` (it answers at once) and `ae_dialogs` (read-only).\n2. If the popup was caused by your own operation (`caused_by_op`), answer OK with\n   `ae_dialog_respond` using the handle from `ae_dialogs`. List it first; it is re-read before the\n   key is pressed. Otherwise ask the user.\n3. Tell the user what it said. It will come back, because the cause is still there.\n4. Run `ae_fonts` action `check_files`. If AE shows the warning again while it runs, it is caused by\n   that call (`caused_by_op` is set): the watcher usually presses OK itself; if it is still open,\n   answer OK with `ae_dialog_respond` as in step 2.\n\n### Diagnosis with what the tools can see\n\n`check_files` finds **file** problems: missing, empty, unreadable or non-font files. It cannot see\nduplicate installs, sibling fonts with identical family, weight and italic flags, a second copy of\nan Adobe-bundled font, damage inside an otherwise valid file, or Adobe Fonts sync state. So:\n- `problem_fonts` above 0: report each font by `postscript` and `location`, with its `problem` and\n  the fix in `note`.\n- `problem_fonts` 0: say that no file is broken (it does not clear the fonts), and move to what only\n  the person can check. `note` says so too. Use `search` with `family` and `check` (`duplicates`,\n  `other_fonts_with_same_dict`) to list candidates: two entries with the same family and style, or\n  `location` in two folders. Names starting \"Adobe Clean\" in a user font folder are suspect.\n- If `adobe_fonts` is above 0 and the warning appears at AE start, ask whether Creative Cloud was\n  running.\n\n### What needs the person\n\nYou cannot install or remove fonts, empty font caches, or restart AE; `ae_run_jsx` is linted against\nfile deletes and quitting. Ask the user to:\n- remove or reinstall the fonts you listed (Windows: Settings, Personalization, Fonts; macOS: Font\n  Book), and remove the duplicate or the second copy of an Adobe font;\n- for an Adobe Fonts font, switch it off and on again in the Creative Cloud app, with Creative Cloud\n  running;\n- with AE closed, delete Adobe's font cache files (`AdobeFnt*.lst`; Windows: AE 2026 keeps its own\n  under `%LOCALAPPDATA%\\Temp\\Adobe\\After Effects\\26.3\\Typesupport` (the folder is named after the\n  version), other Adobe apps use\n  `%LOCALAPPDATA%\\Adobe\\TypeSupport` and the CT Font Cache folders under `%APPDATA%\\Adobe`); AE\n  rebuilds them on start. A stale cache is the least likely cause: try it after the font fixes;\n- **restart AE** after any font change. Fonts changed while AE is open raise the warning again, and\n  AE's list may be stale. After the restart, read again with `in_use` and `check`.\n\nSave the project before asking for a restart (`ae_save`).\n\n## Rules of thumb\n\n- Never call a font \"missing\" from `search` alone, or from `in_use` while `missing_known` is false.\n- Never run a real `replace` without a dry run first, a saved project and a checkpoint.\n- Do not answer a popup you did not cause, or any popup whose OK talks of replacing, losing or\n  erasing, without the user. `ae_dialog_respond` refuses it without `allow_destructive` and a\n  `user_instruction`.\n- Tell the user which fonts changed, how many layers, and what the glyph check said.\n",
  },
  "ae-live-session": {
    "SKILL.md": "---\nname: ae-live-session\ndescription: \"How to work in After Effects through the chroma-ae MCP while a person is editing the same project live: inspect before writing, target guards (expect), checkpoints and undo, write outcomes (applied, no_op, not_applied, unknown) and the quarantine, idempotency keys, the single-writer queue and busy or Stop refusals, popups and the dialog rules (ae_dialogs, ae_dialog_respond), asking the user (ae_plan, ae_ask_user), long renders (render queue, aerender, render lock, the AE 26.3 render hang), and saving. Load at the start of any session that changes an open After Effects project, after a timeout, busy, queued, guard or Stop refusal, when a popup appears, before starting a render or saving, or when the user says they are working in After Effects at the same time.\"\nmetadata:\n  version: \"1.0.0\"\n---\n\n# Working in After Effects beside a person\n\nThe user is probably editing the same project while you work. They can move a layer, open a dialog\nor press Stop at any moment. The server is built for that: every write is guarded, checkpointed and\nread back. Your job is to keep its assumptions true: look first, change one thing at a time, say\nwhat you did, and stop when the state is not what you thought.\n\n## Which tools are close at hand\n\nCore tools (always in the list) include `ae_plan`, `ae_status`, `ae_get_project`, `ae_get_comp`,\n`ae_comp_tree`, `ae_get_layer_props`, `ae_find_layers`, `ae_get_keyframes`, `ae_set_property`,\n`ae_batch_set`, `ae_set_text`, `ae_create_layer`, `ae_create_comp`, `ae_layer_ops`,\n`ae_import_footage`, `ae_add_effect`, `ae_set_effect`, `ae_save`, `ae_snapshot_frame`, `ae_run_jsx`,\n`ae_dialogs`, `ae_dialog_respond`, `ae_skill_run`, `ae_render_queue_add`, `ae_render_queue_edit`,\n`ae_render_queue_status`, `ae_render_queue_render`, `ae_render_queue_render_status`,\n`ae_aerender_start`, `ae_aerender_status`, and the three meta-tools.\n\nNot in the core list, so reach them with `ae_search_tools { query }` or `{ pattern: \"^ae_checkpoint\" }`,\nthen `ae_invoke_tool { name, arguments }` (full schema from `ae_get_tool_schema { name }`):\n`ae_session_changes`, `ae_checkpoint_create`, `ae_checkpoint_list`, `ae_checkpoint_revert`,\n`ae_auto_checkpoint`, `ae_comp_fingerprint`, `ae_comp_diff`, `ae_recent_ops`, `ae_quarantine_status`,\n`ae_acknowledge`, `ae_ask_user`, `ae_project_session`, `ae_verify_render`. Clients on the full toolset\n(HTTP header `X-Chroma-Toolset: full`, or `CHROMA_AE_MCP_TOOLSET=full` for the relay) see all of them\nlisted; some appear there as one tool with an `action` field (`ae_checkpoint { action: \"create\" |\n\"list\" | \"revert\" }`). The old names still work.\n\n`ae_search_tools` and `ae_get_tool_schema` never touch After Effects, so they answer while it is busy.\n\n## 1. Inspect before you write\n\n1. Start a new task with `ae_plan { request, intent?, comp_id?, layers?, answers? }`. It reads the open\n   project once and returns what it took the request to mean, questions whose answers change the work,\n   a plan with a tool per step and hazards. Whether you ask the questions or use its stated defaults\n   follows the user's \"Ask first\" button in the panel; the result says which.\n2. `ae_status` gives the open project's path (a marker if never saved: copy it exactly), the dirty flag, the active\n   comp, selected layers and the quarantine list. `detail: true` adds the Project panel selection, the\n   time, selected properties and warnings. Selection can change between this read and your write, so\n   act on explicit ids and indexes, not on \"the selected layer\".\n3. Read what you will touch: `ae_comp_tree`, `ae_find_layers`, `ae_get_comp`, `ae_get_layer_props`\n   (`meta: true` for what a property accepts), `ae_get_keyframes`. Read tools change nothing, not even\n   time or selection.\n4. After your first write, `ae_session_changes` (or the `user_changed` line on each later write result)\n   tells you what the user changed since your last write: another project open, items added or\n   removed, layers added or edited, selection or work area changed, a restart. If it says anything\n   changed, re-read before writing. `rebase: true` moves its baseline to now. Before your first write\n   there is no baseline.\n5. Every write names its target: `expect: { project_path, comp_id? }`, copied from `ae_status`. If AE\n   has something else open, the write is refused with `kind: \"guard\"` and nothing changes. A guard\n   failure means stop and re-read, never retry with the same expectations.\n\n## 2. Checkpoints and undo\n\n- **Automatic.** Before each write the server copies the saved `.aep` to\n  `<projectdir>/_mcp_checkpoints/<name>_<stamp>_auto-<tool>.aep` and puts it in the result as\n  `checkpoint`. It is the last save. If the user has unsaved work, `checkpoint.unsaved_changes_not_included`\n  is true and the copy lacks it. Writes between two saves share one copy. Unsaved projects and files\n  over 250 MB are skipped (`ae_auto_checkpoint { enabled?, max_mb? }`; change it only if the user asks).\n- **Manual.** `ae_checkpoint_create { expect, label? }` before something large. `ae_checkpoint_list\n  { expect }` lists them.\n- **Receipts.** Each write returns a `receipt` read back in a separate call: what differs before and\n  after. A mismatch in it means the write did not do what you meant. `ae_comp_fingerprint { comp_id }`\n  (returns an `id`) then `ae_comp_diff { before_id }` show every changed property for a stretch of work.\n- **One undo step per call.** The user's Ctrl+Z (Cmd+Z on macOS) takes back a whole tool call. Saves,\n  project open and close, renders and font replacement have no undo step.\n- **Prefer the checkpoint to asking the user to press Ctrl+Z.** AE exposes no undo history, so\n  `ae_session_changes` can only say an undo step is \"not_reachable\" (provably gone) or \"possibly_reachable\".\n- `ae_checkpoint_revert { expect, checkpoint_path, discard_changes? }` opens the checkpoint file itself.\n  It refuses when the project has unsaved changes unless `discard_changes: true`: that throws the user's\n  work away, so ask first. Saving afterwards overwrites that checkpoint; make a new one if you need it.\n\n## 3. Write outcomes\n\nEvery write result has `ok` and, for writes, `outcome`:\n\n| `outcome` | Meaning | What you do |\n|---|---|---|\n| `applied` | It ran and was read back. | Check `receipt`. Tell the user in a line. |\n| `no_op` | It ran and changed nothing (already the way you asked). | Do not repeat it. |\n| `partial` | Part of a batch applied (`ae_batch_set`: earlier ops or chunks applied, a later one failed; see `done` and `failed_chunk`). | Do not rerun the whole batch. Re-read state and send only what is left. |\n| `not_applied` | Refused before anything changed: invalid arguments, a failed guard, quarantine, a busy or queued refusal. | Fix the cause (the message names it), then call again. |\n| `unknown` | The call timed out or failed after sending. Part of it may be in the project. | Never resend. Read state, then decide. |\n\n`next_steps` in a result is a list of what to do next (for `unknown`: read the state with `ae_comp_diff`\nor the read tools, one Ctrl+Z removes the call's undo group, the checkpoint holds the project as it\nwas). Follow it.\n\n**The quarantine.** A write that times out is quarantined and every other write is refused (`kind:\n\"quarantined\"`) until it is cleared. Reads still work. To clear it: `ae_status` (lists it), inspect the\nproject with read tools, then `ae_acknowledge { op_id, note }` where `note` says what you found. A write\nthat was in flight when AE or the panel service went down is quarantined the same way and shown by\n`ae_session_changes`. Nothing is retried automatically. `ae_recent_ops` lists the last 200 writes with\ntheir outcomes, so after a lost reply you can see whether one ran.\n\n## 4. Idempotency keys\n\nGive every write a fresh `idempotency_key` (a string up to 128 characters, such as `\"dim-bg-comp7-v1\"`).\nEvery tool that takes `expect` or checkpoints has it, ae_run_jsx and ae_skill_run included.\n\n- Same key, same arguments, same client and same project: the second call returns the first answer with\n  `idempotent_replay: true` and `first_called_at`, and does not run again. If the first is still running,\n  the second waits for it.\n- Same key with different arguments: refused with `code: \"idempotency_key_reused\"`, `outcome:\n  \"not_applied\"`. Use a new key for a new write.\n- A result that changed nothing (`not_applied`, a guard, queued or quarantine refusal, invalid\n  arguments) is not kept, so sending it again after fixing the cause runs it. Anything else is kept,\n  an `unknown` result included: resending it gets the same `unknown` back. That is deliberate.\n- Keys are scoped to the tool, the client and `expect.project_path`; at most 200 are kept, for one hour.\n- Name keys after what the write does. A reused name in another project is a new write.\n\n## 5. Busy, queued and Stop\n\n- **One writer.** The server runs one operation at a time, reads and writes alike, in order. A call\n  that waits more than 600 s is dropped with `kind: \"queued\"` and nothing ran. Wait for your own call\n  to finish before sending the next.\n- **Busy.** If a popup, someone else's script or a manual render has held AE for 15 s or more, calls\n  are refused at once with `kind: \"queued\"` and `actual.busy` (`cause`: `rendering`, `dialog_open`,\n  `script_running` or `unknown`; the popups; `next_steps`). Nothing was sent. Read the popups with\n  `ae_dialogs`, tell the user what holds AE, and call `ae_status` (it answers at once, with `busy`) after\n  about 30 s. Never retry in a loop.\n- **Timeouts.** A call waits 120 s for AE. On timeout the call is not cancelled: it may still be running\n  or may have finished. A timed-out write is `unknown` and quarantined (section 3). Later calls are\n  refused as busy until AE finishes it.\n- **Stop.** The panel has a Start/Stop button at the top. While the user has stopped it, every call is\n  refused before it reaches AE, with `kind: \"queued\"` and a message that starts \"The user stopped the MCP\n  in After Effects\". Calls waiting in the queue are refused too; the one already running finishes.\n  Tell the user in one line, stop calling tools, and wait until they say they have pressed Start. Do not\n  retry. Reads are refused as well, so verify state after Start, before any resend of a write.\n\n## 6. Popups\n\nAE shows modal popups (missing fonts, overwrite warnings, \"file not found\"). They block its scripting\nthread. Popups are never suppressed.\n\n- **The watcher.** The panel service watches for them. A popup raised by your own call with one OK-like\n  button is pressed at once, because your call would wait on it. Progress windows (Cancel or Stop only)\n  are left alone. Any other popup is put to the user in the panel (\"After Effects asks\", with a\n  screenshot and its buttons), and in the client too when the client takes questions (section 7).\n- **Reports.** What happened is added once to your next tool result as `popups`: `pressed_for_you`,\n  `answered_by_user`, `closed_in_after_effects` or `open` (with `handle`, `buttons`, and buttons marked\n  `only_in_after_effects` that the user must click). Tell the user in a line what each popup said and\n  what was pressed. For a missing font offer `ae_fonts` with `check_files`; for missing files,\n  `ae_collect_relink`.\n- **`ae_dialogs`** lists open popups (read-only): `handle`, `title`, `text`, `buttons`, `screenshot`,\n  `caused_by_op`, `kind` (`info`, `question`, `destructive`; advisory). Look at the screenshot when\n  unsure. Call it when a call timed out or came back busy.\n- **`ae_dialog_respond { handle, button, reason, check?, allow_destructive?, user_instruction? }`.**\n  `reason` is always required: say why you answer and why that button.\n  - `caused_by_op` null (the popup is not from your own running call): refused (`refused_not_caused_by_our_op`)\n    unless `user_instruction` quotes the user's words.\n  - A destructive button (Save, Don't Save, Replace, Delete, Overwrite, Discard, Remove, Revert) needs\n    both `allow_destructive: true` and a `user_instruction` quoting the user (`refused_destructive_button`).\n    OK or Yes on a popup whose text is about replacing, overwriting, deleting or losing something needs\n    the same (`refused_destructive_dialog`).\n  - On a popup AE paints itself, only Cancel, No or Close (sent as Escape) and the default OK, Yes or\n    Continue (sent as Enter) can be pressed. Other buttons return `button_not_default` or\n    `button_not_answerable`: ask the user to click them. `dialog_changed` and `dialog_gone` mean read again.\n  - If `closed` is false, nothing else is tried; ask the user.\n  - Every answer is logged. Tell the user what you dismissed and what it said.\n\n## 7. Asking the user\n\n- `ae_plan` says up front which choices are the user's. Ask when a choice changes the look, the timing\n  or the files (which variant, which easing, where to save), not for routine ones.\n- `ae_ask_user { question, options (2 to 8, each id and label), kind?, multi_select?, allow_other?,\n  context?, wait_seconds? }` asks in the Chroma AE MCP panel and waits (default 120 s, at most 600). Show\n  rather than describe: give each option an `image_path` (a PNG or JPEG from `ae_snapshot_frame`), or\n  `kind: \"ease\"` with a `curve` per option. Results: `answered`, `dismissed`, or `waiting` with an\n  `ask_id`. For `waiting`, call again with `{ ask_id }` to keep waiting; the question stays in the panel.\n  If dismissed, go on with a sensible default and say which. Ask one thing at a time.\n- If the client declared the `elicitation` capability at `initialize` (MCP revisions up to 2025-06-18),\n  a plain single choice with no pictures is asked in the client's own prompt (`via: \"elicitation\"`).\n  A client on MCP 2026-07-28 is never asked in its own prompt (that revision has no server-to-client\n  requests), and ease curves, several answers and pictures are always asked in the panel. Do not\n  assume the user sees it in the chat: say in the chat that you have asked in the After Effects panel.\n\n## 8. Long renders\n\n- **Do not block on a render.** Both render tools return at once with a job id. Poll the status tool;\n  `wait_seconds` (0 to 30) waits for a change, so one call replaces several polls. The status tools never\n  touch AE.\n- **Prefer `ae_aerender_start`** (a separate background process; AE stays free). It needs a saved,\n  non-dirty project, so ask the user to save first. One aerender job runs at a time and a new one starts\n  at least 20 s after the last. Follow it with `ae_aerender_status { wait_seconds }`.\n- **`ae_render_queue_render`** is AE's own render. Tell the user first: AE is locked for the whole render,\n  the user cannot work in it and cannot reach Stop (measured). It is for when aerender cannot be used, or\n  for a project that is unsaved or has unsaved changes (it renders it as it is now); on a dirty project\n  ask the user to save first all the same, because the render cannot be stopped. Keep these renders short. While it runs, every tool that needs AE is refused\n  at once with `kind: \"queued\"`. `ae_render_queue_render_status`, `ae_dialogs`, `ae_dialog_respond` and\n  `ae_status` still answer. If the lock does not clear after AE stops rendering, restarting AE clears it,\n  or the user presses \"Clear render lock\" in the panel. Never ask the user to press Render themselves.\n  Media Encoder only with `engine: \"media_encoder\"` and `user_confirmed: true`, after asking.\n- **An existing output file** is refused unless `overwrite: true`. After Effects then asks to overwrite,\n  and answering OK is destructive: it needs the user's instruction.\n- **Check the output** with `ae_verify_render` on one real file or frame once the job ends.\n- **The AE 26.3 render hang** (`render_hang_env_light`). On AE 26.3, an Advanced 3D comp whose environment\n  light takes its image from a layer, with another 3D layer, never finishes rendering. `ae_snapshot_frame`\n  and the frame tools built on it refuse it before anything renders, and `ae_plan` lists it as a hazard.\n  Tell the user: to render a frame, clear that light's Source (Light Options) or switch the light off for\n  the check. The comp was not changed; do not change it for them. If a frame was never written\n  (`frame_not_written`), frame renders are refused (`frame_render_pending`) until it appears or AE is\n  restarted: tell the user to save (`ae_save`) and restart After Effects.\n\n## 9. Saving\n\nSave only when the user asks, or when a tool needs a saved project and you have asked them. A save\noverwrites their file, and it changes what the next checkpoint captures.\n\n- `ae_save { expect, backup?, save_as?, increment? }`. By default it first copies the file on disk to\n  `<projectdir>/_mcp_backups/<name>_<stamp>.aep`. `save_as: { path, overwrite? }` is the only way to\n  save an untitled project; it points the open project at the new file and leaves the old file and its\n  checkpoints where they were. `increment: true` saves as the next free `_vNNN` and never overwrites.\n- Never call `project.save()` in a script (the safety lint refuses it), and do not save to \"make a\n  checkpoint\". Use `ae_checkpoint_create`.\n\n## Short rules\n\n1. Look, then write. Name the target in `expect`.\n2. One write at a time; wait for it.\n3. Give every write an `idempotency_key`.\n4. On `unknown`, a timeout or a quarantine: read, never resend.\n5. On busy, queued or Stop: tell the user, wait, do not loop.\n6. On a popup: read it, tell the user what it said, answer only under the dialog rules.\n7. Tell the user what you changed in a line. Mention the checkpoint when it matters.\n",
  },
  "captions": {
    "NOTICE.md": "# Sources and licences\n\nThis skill is Chroma's own synthesis, written in its own words. Standards are cited by number\nand link; no style guide is quoted at length. Researched 2026-11-06.\n\n## Standards and guides (facts and numbers, linked)\n\n| Source | Used for |\n|---|---|\n| [Netflix English (USA) Timed Text Style Guide](https://partnerhelp.netflixstudios.com/hc/en-us/articles/217350977-English-USA-Timed-Text-Style-Guide) | 20 / 17 cps, 42 characters, 2 lines, duration limits, SDH conventions |\n| [Netflix Subtitle Timing Guidelines](https://partnerhelp.netflixstudios.com/hc/en-us/articles/360051554394-Timed-Text-Style-Guide-Subtitle-Timing-Guidelines) | minimum gap, closing gaps, shot-change rules |\n| [BBC Subtitle Guidelines](https://www.bbc.co.uk/accessibility/forproducts/guides/subtitles/) | words per minute, line length, gaps, synchronisation, speaker colours |\n| [DCMP Captioning Key](https://dcmp.org/learn/597-captioning-key---text) | 32 characters, minimum and maximum duration, presentation rates |\n| [Ofcom TV access services](https://www.ofcom.org.uk/tv-radio-and-on-demand/information-for-industry/guidance/tv-access-services) | UK broadcast subtitling duties and quality expectations |\n| [W3C WCAG 2.2](https://www.w3.org/TR/WCAG22/) (1.2.2, 1.2.4, 1.4.3) | caption requirements and the 4.5:1 text contrast |\n| ITU-R BT.1359-1 | audio/video sync tolerances |\n\n## Skills and projects whose ideas were adapted\n\n| Source | Licence | Used for |\n|---|---|---|\n| [github/awesome-copilot: caption-qa](https://github.com/github/awesome-copilot) | MIT | the idea of a per-standard lint (cps, line length, duration, gaps), \"retime before rewording\", default-standard rule |\n| [vargHQ/skills: caption-styles](https://github.com/vargHQ/skills) | MIT | caption style families for social, and how they differ in chunk size |\n| [clueso-ai/skills: add-ai-captions, add-animated-captions](https://github.com/clueso-ai/skills) | Apache-2.0 | workflow order (transcribe, review, style, burn in) and animated word-highlight options |\n| [heygen-com/hyperframes](https://github.com/heygen-com/hyperframes) (captions references and rules) | Apache-2.0, (c) HeyGen | Whisper failure modes (invented text over silence, `.en` models translating, over 20% music-note tokens), word grouping by energy, the plain-sidecar habit |\n| [Remotion captions](https://www.remotion.dev/docs/captions) | documentation, linked only | what `createTikTokStyleCaptions` does |\n\n## Ideas only (no licence stated in the downloaded copy; nothing copied)\n\n45ck/content-machine karaoke-ass-captions, AI-Builder-Club karaoke-captions, HUSS41N\nshorts-text-safe-zones, JosiahSiegel viral-video-animated-captions, appariciojunior captions,\nbrowser-use video-use, calesthio captions-media-accessibility, damionrashford ffmpeg-captions,\nkatareayush video-captions, lattifai omnicaptions, social-media-skills captions-and-clipping,\nvideo-db video-subtitles. Read for the shape of the problem (karaoke timing, safe zones, ffmpeg\nburn-in); every rule here was re-derived from the published standards above.\n\nA commercial caption product's marketing page was read for feature ideas only (word-level\nediting, per-standard checks). Nothing copied.\n\n## Numbers computed here\n\nContrast figures for a black box behind white text were computed with the WCAG relative\nluminance formula (`references/sdh-and-speakers.md` states the background they assume).\nPlatform UI zones are approximate, from ad specs and third-party templates.\n",
    "SKILL.md": "---\nname: captions\ndescription: \"Make, check and ship captions and subtitles that meet a published standard: transcribe, chunk, time, break lines, style, QA and export. Use for captions, subtitles, SDH, closed captions, open captions, burn-in, SRT, VTT, WebVTT, TTML, IMSC, SCC, karaoke captions, word highlight, kinetic captions, social captions, TikTok / Reels / Shorts captions, transcript, transcribe, Whisper, ElevenLabs Scribe, reading speed, cps, line breaks, caption QA, safe zone, Netflix / BBC / DCMP / Ofcom standards, accessibility and WCAG, in After Effects (chroma-ae MCP), Premiere, Remotion, HyperFrames or any other tool. Trigger phrases: 'add captions', 'subtitle this', 'caption this reel', 'burn in subtitles', 'make an SRT', 'check these captions', 'too fast to read', 'TikTok captions', 'word by word captions', 'accessible captions'.\"\nmetadata:\n  version: \"1.0.0\"\n  sources: see NOTICE.md\n---\n\n# Captions\n\nOne skill for turning speech into captions that people can read, from a transcript to a delivered\nfile. The rules are numbers from published guides, so a caption can be measured, not admired.\nWritten in Chroma's own words; sources and licences are in `NOTICE.md`.\n\n**Load only what the task needs:**\n\n| Task | Read |\n|---|---|\n| Which limits apply; sources and links | `references/standards.md` |\n| Chunking, timing, gaps, line breaks, shot changes | `references/timing-and-breaks.md` |\n| Sound events, speakers, colours, music, contrast | `references/sdh-and-speakers.md` |\n| 9:16 reels, shorts, word highlight, platform zones | `references/social-and-platforms.md` |\n| Transcribing, Whisper and Scribe failure modes, clean-up | `references/asr.md` |\n| SRT, WebVTT, TTML/IMSC, SCC, sidecars, After Effects limits | `references/formats.md` |\n| Doing it with the chroma-ae MCP tools, Remotion, HyperFrames | `references/chroma-ae-workflow.md` |\n\nFor motion rules around captions (beats, keeping them out of the action), see\n`chroma-motion-director` (`references/sound-and-captions.md`). This skill owns the caption rules.\n\n## Pick the destination first\n\nNo target means no answer to \"are these captions OK?\". Ask, or state the default you used.\n\n| Destination | Standard | Notes |\n|---|---|---|\n| Netflix, streaming, most online video | Netflix English (adult) | the default when nothing is named |\n| Children's programmes | Netflix English (children's) | 17 cps instead of 20 |\n| UK broadcast and iPlayer-style delivery | BBC | words per minute, 37 characters broadcast |\n| US education, training, e-learning | DCMP Captioning Key | 32 characters, slower rates |\n| 9:16 social (TikTok, Reels, Shorts) | house social preset | short chunks, platform safe zones |\n| Legal or accessibility claim | WCAG 2.x plus the above | 1.2.2 (A) prerecorded, 1.2.4 (AA) live |\n\n## Key numbers\n\n| Rule | Netflix adult | Netflix kids | BBC | DCMP |\n|---|---|---|---|---|\n| Reading speed | 20 cps | 17 cps | 160-180 wpm (about 0.33 s a word) | 130-160 wpm by level |\n| Characters per line | 42 | 42 | 37 broadcast; online 68% of a 16:9 frame | 32 |\n| Lines | 2 | 2 | 2 | 2 |\n| Shortest caption | 20 frames at 24 fps (5/6 s) | same | not fixed | 40 frames |\n| Longest caption | 7 s | 7 s | not fixed | 6 s |\n| Gap between captions | 2 frames minimum | same | if a pause is left, 1 s or more (1.5 s better) | not fixed |\n\nFull table with links: `references/standards.md`.\n\nAlways:\n- Appear on speech onset (or a frame or two before); linger about 0.5 s after speech where space allows.\n- Two lines at most, bottom-heavy (the lower line longer) when both are needed.\n- Break at grammar, not at the character count (`references/timing-and-breaks.md`).\n- Colour is never the only cue for a speaker (colour-blind viewers, monochrome sets).\n- Text contrast 4.5:1 or better; a black box behind the text at 60% opacity or more (75% over busy footage).\n- Ship a plain sidecar (SRT or VTT) next to any burned-in version.\n- Review every name, number and brand word by eye. Speech-to-text gets them wrong with confidence.\n\n## The workflow\n\nSeven steps. In After Effects each maps to a chroma-ae tool (`references/chroma-ae-workflow.md`).\n\n1. **Destination and style.** Standard preset, caption kind (subtitle-style, phrase chunks, single\n   word), language, SDH or dialogue only.\n2. **Transcribe, or take the client's file.** Transcribing with Scribe sends the audio to a\n   third-party service: ask first. A supplied SRT or VTT skips this step.\n3. **Read the transcript.** Invented lines over silence or music, wrong language, lost\n   punctuation, names. Fix before chunking, not after (`references/asr.md`).\n4. **Plan against the standard, with cut times.** Chunk, break, time, merge, then list what\n   changed and what still violates. Give the planner the shot changes so it can respect them.\n5. **Review the plan.** Read the change list and every violation. A violation that retiming\n   cannot fix is a rewording decision for a human; never silently cut the speaker's words.\n6. **Write the captions** into the comp (layers, one layer, per word, or a template), inside the\n   platform safe zones, with a backing box if the footage is busy.\n7. **Check, export, look.** Read them back, lint against the standard again, export the sidecar,\n   then look at frames (first caption, a two-line caption, the fastest caption, a cut, the last\n   caption) at phone width. Say which checks were measured and which were only looked at.\n\n## Chunking modes\n\n| Mode | Shape | Use for | Avoid for |\n|---|---|---|---|\n| Subtitle-style | 1-2 lines, a full phrase, standard limits | dialogue, interviews, anything going to a platform or broadcaster | nothing; the safe default |\n| Phrase chunks | 2-4 words at a time, capped with `max_words` | punchy social edits, product films, explainers | fast speech with long sentences |\n| Single word | one word at a time | very short hooks and slogans (under about 8 words) | anything longer; fast speech |\n\nSingle-word display hurts comprehension: no word lands next to its neighbours, viewers who read\nahead lose the line, and fast speech flashes words for under 8 frames. Two to four words is the\nworking minimum for speech. Merge any word shorter than 8 frames into its neighbour. Keep numbers\nwith their units (\"40 per cent\", \"3 million\") and names together. Start a word highlight a frame\nor two early so it reads as in sync, not late.\n\n## Common mistakes\n\n- Using 42 characters per line for 9:16 social; a portrait phone line holds about 25 (`references/social-and-platforms.md`).\n- Burning in with no sidecar. Nobody can then fix a typo, translate, or search the text.\n- Trusting word timestamps to the frame; they drift 50-100 ms.\n- Ending a line on \"the\", \"of\", \"and\", \"to\", \"I\", or splitting a first name from its surname.\n- Captions over the platform UI (bottom 660-672 px, right-hand button column on 1080x1920).\n- Red and green speaker colours with no label.\n- Fitting the reading speed but ignoring the cut: a caption that straddles a shot change by two frames flashes.\n",
    "references/asr.md": "# Speech to text\n\n## Which tool\n\n- `ae_transcribe` uses ElevenLabs Scribe. It uploads the audio to a third-party service. For\n  client audio, ask first, then pass `confirm_upload: true`.\n- Whisper (local, open) keeps audio on the machine. Choose it for confidential work.\n- A client-supplied SRT or VTT is better than either; use it and skip transcription.\n\n## Failure modes (read the transcript before using it)\n\n| Failure | Sign | Response |\n|---|---|---|\n| Invented text over silence or music (hallucination) | \"Thank you.\", \"Thanks for watching\", repeated lines, words starting inside a silent tail | drop words starting inside silence below about -35 dB for 0.6 s or more (`cleanup`) |\n| `.en` models translating non-English audio | English output for foreign speech | use a multilingual model and set the language |\n| Word timestamp drift | words 50-100 ms off the audio | nudge the whole track; do not trust the frame |\n| Word-level output loses punctuation and casing | a stream of lowercase words | restore from sentence-level output or a script, then chunk |\n| Music-note tokens | more than 20% of tokens are note symbols or `?` blocks | retry with a different or larger model, or take lyrics from the person |\n| Unspaced scripts (Chinese, Japanese) | a whole sentence as one word, wrong script | split into short phrases and spread the time by character count; check characters |\n| Names, numbers, brands | confident but wrong | always review by eye |\n| Speaker labels | missing or swapped | add by hand for SDH |\n\n## Clean-up options\n\n`ae_captions_plan` takes a `cleanup` option to drop non-word tokens, drop words inside trailing\nsilence, and merge fragments, and reports what it removed in the `CleanupReport`. It does not\ncheck spelling or meaning.\n\n## Review pass\n\nWatch it once with sound at normal speed with the captions on. Note: every proper name, every\nnumber, every place the caption disagrees with what was said, every caption on screen over music\nor silence. Fix the transcript, then plan.\n",
    "references/chroma-ae-workflow.md": "# Doing it with the chroma-ae MCP tools\n\nTool names are exact. Read each tool's own description for its full input shape; this page\nsays when to use which.\n\n| Tool | Does |\n|---|---|\n| `ae_transcribe` | ElevenLabs Scribe word-level transcript of a comp's audio (rendered in the background) or an audio/video file. Uploads client audio to a third-party US service: ask first, then `confirm_upload: true`. Returns `transcript_path` and `offset` for the planner |\n| `ae_captions_plan` | chunks, breaks and times words against a standard; returns the plan, the `changes` and the `violations`. Writes nothing |\n| `ae_detect_cuts` | finds shot changes; `mode: \"list\"` returns the cut times for `cut_times` |\n| `ae_captions` | writes captions to the comp (guarded, one undo step) |\n| `ae_captions_read` | reads existing captions back: text, timing, extents against the safe area |\n| `ae_captions_qa` | lints an SRT/VTT file, a plan or the caption layers against a standard |\n| `ae_captions_export` | writes an SRT, VTT or TTML sidecar, by default next to the project |\n| `ae_export_mogrt` | exports a template comp (from `ae_captions` `make_template`) as a .mogrt for Premiere |\n\n## ae_captions_plan options (ae_captions takes the same)\n\n| Option | Values and use |\n|---|---|\n| `standard` | `netflix_adult`, `netflix_kids`, `bbc`, `dcmp`, `social_9x16`: sets the limits and turns on fixing |\n| `fix` | default true with a standard: extend, then merge, then split; `false` only reports |\n| `min_gap_frames`, `close_gaps_under` | gap rules (default 2 frames; gaps under 0.5 s close to 2 frames) |\n| `cut_times` | shot changes from `ae_detect_cuts` (comp seconds); in/out times respect them |\n| `cleanup` | `drop_after_s`, `drop_music_tokens`, `min_word_s`, `remove_fillers`, `remove_stutters`, `glossary`, `case`, `strip_punctuation` |\n| `max_words` | cap on words per caption (phrase chunks) |\n| `single_word` | one word at a time (hooks only); short words merge, names and numbers stay whole |\n| `highlight_lead_frames` | how many frames early a word highlight starts (default 1) |\n| `speaker_style` | `color` (BBC order), `hyphen` (two speakers, one caption), `label` (`NAME: `); `speaker_names`, `speaker_colors` |\n| `accessibility` | never colour alone: adds a label at each speaker change when `speaker_style` is `color` |\n| `sdh` | `sound_events` (default on: `[laughter]` captions from ElevenLabs audio events), `lyric_ranges` (italic, music notes) |\n| `transcript.offset` | the `offset` that `ae_transcribe` returns |\n\n## ae_captions modes\n\n| `mode` | Result | Use for |\n|---|---|---|\n| `layers` | one text layer per caption | most work; easy to edit and animate per caption |\n| `single` | one text layer whose text changes over time | clean timeline, simple styles |\n| `words` | one layer per word, laid out as the caption; words build on as spoken | per-word animation |\n| `template` | one instance per caption of an Essential Graphics template comp, its fields (e.g. \"Line 1\", \"Line 2\") filled | brand-styled designs |\n\nOther options: `platform` (`reels_9_16` = safe on all three apps, the 9:16 default; `tiktok_9_16`,\n`instagram_reels_9_16`, `youtube_shorts_9_16`), `parent_to_null` (one null moves the whole set),\n`precompose`, `match: \"time\"` (update existing captions by time instead of by name), `highlight`\n(the current word), `look` (`pop`, `pill_slide`, `fill_sweep`, with `look_options`), `box` (the\nbacking box; 60% opacity or more), and `make_template` (a styled caption comp with Essential\nGraphics controllers, then `ae_save` and `ae_export_mogrt` for Premiere).\n\n## Recommended workflow\n\n1. `ae_transcribe` (after asking) or take the client's SRT.\n2. Read the transcript; fix the problems in `asr.md`.\n3. `ae_detect_cuts` with `mode: list` to get `cut_times`.\n4. `ae_captions_plan` with a standard, `cut_times`, `cleanup`, and the chunking options.\n5. Read the changes and the violations. Decide the rewordings a human has to make.\n6. `ae_captions` to write (layers, single, words or template), with the platform zone and box.\n7. `ae_captions_read` to confirm what is in the comp, then `ae_captions_qa` against the standard.\n8. `ae_captions_export` for the SRT or VTT sidecar.\n9. Look at frames: `ae_contact_sheet` or `ae_snapshot_frame` at the first caption, the busiest,\n   a cut, and the last. Check at phone width.\n\n## Other tools\n\n- Remotion: `@remotion/captions` defines a `Caption` type and parsers; `createTikTokStyleCaptions`\n  groups words into pages that switch on a time window (a combine-tokens-within-milliseconds\n  setting controls chunk size). See the [Remotion captions docs](https://www.remotion.dev/docs/captions)\n  and the `remotion-captions` skill. It does not enforce a broadcast standard; run the numbers\n  from this skill over its output.\n- HyperFrames ([heygen-com/hyperframes](https://github.com/heygen-com/hyperframes), Apache-2.0)\n  has a `transcribe` command that writes word timings (and `--to srt` or `--to vtt` sidecars) and a\n  caption-style registry. Its default model translates non-English speech to English; pass the\n  model and language explicitly (`asr.md`).\n",
    "references/formats.md": "# File formats\n\nAlways ship a plain sidecar next to a burned-in version. It can be fixed, translated, searched\nand read by assistive tech. The burned-in file cannot.\n\n| Format | Use | Gotchas |\n|---|---|---|\n| SRT | the universal sidecar | see below |\n| WebVTT (.vtt) | web video, HTML5 `<track>` | see below |\n| TTML / IMSC | broadcast and streaming delivery | see below |\n| SCC (CEA-608) | US broadcast and legacy | see below |\n\n## SRT\n\n- Numbered cues, a timecode line, text, a blank line.\n- Timecode `00:00:01,000 --> 00:00:03,500`: a comma before the milliseconds.\n- UTF-8 (no byte-order mark if the player is picky).\n- No styling standard. `<i>` works in many players but is not part of the format; test the\n  target. Colours and positions do not travel.\n- Cue numbers must run in order, times must not go backwards.\n\n## WebVTT\n\n- First line `WEBVTT`, then a blank line.\n- Timecode with a period: `00:00:01.000 --> 00:00:03.500`; hours may be dropped.\n- Cue settings after the times: `line`, `position`, `align`, `size`.\n- `<v Name>` voice spans identify speakers; `<i>`, `<b>`, `<c.class>` allowed.\n- Style with `::cue` CSS. Support differs by player.\n- `NOTE` blocks are comments.\n\n## TTML and IMSC\n\n- XML. Regions use `tts:origin` and `tts:extent` in percent, so they scale with the frame.\n- `ttp:timeBase` (media, smpte); `ttp:frameRate` for frame timing; check the profile\n  (IMSC1 text or image) the receiver needs.\n- Styles are explicit in the file; BBC's guide gives the EBU-TT-D details for online delivery.\n- A schema-valid file can still be rejected by a platform's own checker.\n\n## SCC (CEA-608)\n\n- Frame-based timecode, usually 29.97 drop-frame (semicolon before frames).\n- 32 columns by 15 rows on screen; for pop-on captions, 2-4 lines are usable in practice.\n- Heavy character restrictions; no full Unicode. Treat it as a delivery conversion, not an\n  authoring format.\n\n## After Effects\n\nAfter Effects has no native SRT or VTT import. The chroma-ae MCP parses transcripts in Node\n(`ae_captions` takes cues; `ae_captions_read` gives them back) and builds text layers. A caption\nset in After Effects can be exported again as SRT, VTT or TTML with `ae_captions_export`. For\nPremiere, `ae_export_mogrt` makes a caption template; Premiere's own caption track takes\nSRT or VTT.\n",
    "references/sdh-and-speakers.md": "# SDH, speakers and contrast\n\nSDH (subtitles for the deaf and hard of hearing) adds what the ear gets and the eye does not.\nPlain captions carry dialogue only. State which you are making.\n\n## Sound events\n\n- In square brackets, lower case: [door slams], [phone buzzing], [applause].\n- Only sounds that matter to the story or the mood. Not every footstep.\n- Put it on its own caption or its own line, timed to the sound.\n- Off-screen speech: the speaker's name in brackets before it, or a colour, plus position if\n  the format allows. Narrator: [Narrator] or the narrator colour.\n- Tone only where the words do not carry it: [sarcastically], [whispering].\n- Do not describe the picture.\n\n## Music\n\n- Song lyrics: italic, with a music note (a note symbol) at the start of each caption and at the\n  end of the last line of the lyric.\n- Instrumental that matters: [tense music] or [upbeat music playing].\n- Silence that matters: [silence]. Rare.\n\n## Speakers\n\n- Two people in one caption: a hyphen at the start of each line, one speaker per line.\n- A new speaker starts a new caption where it can, so the colour or label change is clear.\n- Name labels (\"MARCUS:\") on first appearance when the speaker is off-screen or unclear.\n\n### Speaker colours\n\nBBC's order for identifying speakers is white first, then yellow, cyan, green:\n\n| Order | Colour | Hex |\n|---|---|---|\n| 1 | white | #FFFFFF |\n| 2 | yellow | #FFFF00 |\n| 3 | cyan | #00FFFF |\n| 4 | green | #00FF00 |\n\nBy BBC convention a narrator takes yellow. Reuse a colour for the same person through the whole\npiece.\n\nColour must never be the only cue. About 1 man in 12 has a colour-vision deficiency, and many\nplayers and monochrome displays drop colour. Pair every colour with a label, a hyphen, or a\nposition. Chroma's `speaker_style` option in `ae_captions_plan` takes a colour, label or dash\nstyle; for accessibility work use a combination.\n\n## Contrast\n\nText against its background: 4.5:1 or better (WCAG 1.4.3; large text 3:1). Over moving footage,\nput a box behind the text rather than hoping the picture behaves.\n\nWhite text over a black box, WCAG contrast ratio by box opacity. Computed with the WCAG\nluminance formula for a pure white backdrop behind the box, which is the worst case (a bright\nsky or a white wall):\n\n| Box opacity | Contrast | Verdict |\n|---|---|---|\n| 50% | about 4.0:1 | fails 4.5:1 |\n| 60% | about 5.7:1 | passes |\n| 75% | about 10.4:1 | passes with margin |\n\nOver a mid-tone image (a mid-grey around sRGB 128), the same boxes score higher: 50% gives\nabout 10.4:1, so the table is a conservative guide. In practice, the box is not the only\nvariable: the picture changes under it. Use 60% as the floor and 75% for busy or bright\nfootage. A box also makes captions readable for viewers with low vision. Outline plus drop\nshadow with no box usually fails over bright areas.\n\nThe box covers the text block plus padding. Do not stretch it to full width: it hides picture.\n",
    "references/social-and-platforms.md": "# Social and 9:16\n\nSocial captions are read on a phone, in a hurry, often with the sound off. They keep the\ntiming and break rules, with shorter lines and bigger text.\n\n## Defaults for 9:16\n\n- Phrase chunks of 2-4 words. Single words only for a short hook.\n- A portrait line holds about 25 characters at BBC's guide (37 in a 75% 16:9 frame is about 25 in\n  a 90% portrait frame). Do not use 42.\n- Large type: 60-80 px on a 1080 x 1920 frame at minimum; check at 360 px wide.\n- Two lines at most; one usually.\n- Put a box or heavy outline behind the text (contrast rules in `sdh-and-speakers.md`).\n- Highlight the current word with colour or scale of at most about 10%; start it a frame or two\n  early. Avoid bounce on every word: it tires the eye and fights the speaker's face.\n- Keep it off the speaker's mouth and eyes, and away from important graphics.\n\n## Platform UI zones (1080 x 1920), approximate\n\nThese are the areas the apps cover with their own buttons and text. They come from ad specs\nand third-party templates, not from the platforms' documentation; apps change their UI, so\nre-check once a year.\n\n| Platform | Top | Bottom | Left | Right |\n|---|---|---|---|---|\n| YouTube Shorts | 288 | 672 | 48 | 192 |\n| Instagram Reels | 269 | 672 | 65 | 65 |\n| TikTok | 240 | 660 | 120 | 120, widening to about 300 below y 840 |\n\nSafe on all three: x 120-888, y 288-1248. Place captions inside it, in the lower part (around\ny 900-1200) so they are clear of the face and the platform's description text.\n\n`ae_captions` has `platform` safe zones for these three and a `safe` option for the combined box.\n\n## Burned-in versus sidecar\n\n- Open (burned-in) captions are the only kind that survive every platform and download; use them\n  for social.\n- Upload a sidecar too (SRT or VTT) wherever the platform accepts one: it makes the post\n  searchable, translatable and correctable, and screen readers can use it.\n- Keep the clean, caption-free master. A burned-in file can never be corrected.\n\n## Speed\n\nSocial viewers read fast, but not that fast: stay near 17-20 cps for dialogue. For hook text,\nshorter is better than faster. Do not shorten a caption's time to make a beat; extend the\nspeech or cut words.\n",
    "references/standards.md": "# Standards\n\nPick one standard per deliverable and say which. Numbers below are from the guides linked in the\nlast column; check the live page before a contractual delivery, as platforms revise them.\n\n| Standard | Reading speed | Line length | Lines | Duration | Gap | Source |\n|---|---|---|---|---|---|---|\n| Netflix English, adult | 20 cps | 42 characters | 2 | min 5/6 s (20 frames at 24 fps), max 7 s | 2 frames minimum | [style guide](https://partnerhelp.netflixstudios.com/hc/en-us/articles/217350977-English-USA-Timed-Text-Style-Guide) |\n| Netflix English, children's | 17 cps | 42 | 2 | same | same | same |\n| BBC | 160-180 wpm, about 0.33 s a word | 37 broadcast (Teletext-derived); online 68% of a 16:9 frame | 2 | not fixed | if left, 1 s minimum, 1.5 s better | [BBC guidelines](https://www.bbc.co.uk/accessibility/forproducts/guides/subtitles/) |\n| DCMP Captioning Key | 130-160 wpm by level | 32 | 2 | min 40 frames, max 6 s | not fixed | [DCMP text](https://dcmp.org/learn/597-captioning-key---text), [rate](https://dcmp.org/learn/601-captioning-key---presentation-rate) |\n| Ofcom (UK broadcast) | no per-cue limits | - | - | sets access-service quotas and quality expectations | - | [Ofcom](https://www.ofcom.org.uk/tv-radio-and-on-demand/information-for-industry/guidance/tv-access-services) |\n| WCAG 2.2 | no numbers | - | - | - | - | [1.2.2](https://www.w3.org/WAI/WCAG22/Understanding/captions-prerecorded.html), [1.2.4](https://www.w3.org/WAI/WCAG22/Understanding/captions-live.html), [1.4.3](https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html) |\n\nNotes:\n- BBC's 160-180 wpm is for live subtitles (raised from 130-150) and is the recommended speed for\n  prerecorded work too; the per-word time (0.33-0.375 s) and the 1 s gap are guidance. Report\n  them as warnings, not failures. The 37-character figure is the broadcast limit, reduced when\n  coloured text is used. Check the current page before quoting a limit to a client.\n- Netflix's timing guide also closes small gaps: where two captions are 3 to 11 frames apart at\n  24 fps, close the gap to 2 frames. Shot-change rules are in `timing-and-breaks.md`.\n- Characters per second (cps) counts every character in the caption, spaces included, divided by\n  the time on screen. Words per minute (wpm) counts words. 20 cps is roughly 200 wpm at 6 letters a\n  word, which is why Netflix is looser than the BBC.\n- DCMP's three levels (lower, middle, upper) set 130, 140 and 160 wpm.\n\n## WCAG in one paragraph\n\n1.2.2 Captions (Prerecorded), level A: synchronised captions for the audio in prerecorded video,\nexcept where the video is a clearly labelled media alternative for text. 1.2.4 Captions (Live),\nlevel AA: captions for live audio. 1.4.3 Contrast (Minimum), level AA: text at least 4.5:1 against\nits background (3:1 for large text); this applies to captions you style yourself. WCAG sets no\nreading speed. Use a broadcast or streaming standard for that.\n\n## Audio and caption sync\n\nITU-R BT.1359-1 gives the tolerances for audio against picture (as recalled from the\nRecommendation; confirm the figures before quoting them): detectable at about +45 ms when audio\nleads and -125 ms when audio lags, acceptable up to about +90 ms and -185 ms. Captions are\njudged against the speaker's lips by the same eyes, so a start within about 2 frames of speech\nonset is safe, and the 50-100 ms drift in word timestamps (`asr.md`) sits at the edge of\ndetectable. A caption that is early reads better than one that is late.\n",
    "references/timing-and-breaks.md": "# Timing, breaks and shot changes\n\n## Order of operations\n\n1. Chunk the words into captions (by sentence, pause or word cap).\n2. Break each caption into lines.\n3. Set in and out times from the words, then apply the limits (cps, minimum, maximum).\n4. Fix gaps and shot changes last, since they move times by frames.\n\n## Chunking\n\n- Break at a sentence end, at a pause of 150 ms or more, or at the word cap, whichever comes first.\n- Subtitle-style: fill to the line limits (42 characters, 2 lines on Netflix). Phrase chunks: 2-4\n  words, set with `max_words`. Single word: only for a short hook.\n- Merge any word shorter than 8 frames into its neighbour so it does not flash.\n- Keep numbers with units, names together, and a title with its name (\"Dr Patel\").\n- Never time two words as one entry; per-word highlights need one entry per word.\n- Highlight a frame or two early (`highlight_lead_frames`): a highlight that lands on the word\n  looks late.\n\n## Timing\n\n- In: the speech onset, or up to 2 frames before. Never later than the first word.\n- Out: the end of speech plus a linger of about 0.5 s where space allows, but never over the\n  next caption's in-time minus the gap, and never past the speaker leaving the shot.\n- BBC: do not anticipate speech by more than 1.5 s or hang on for more than 1.5 s after it.\n- Minimum duration: 20 frames at 24 fps (Netflix), 40 frames (DCMP). A one-word caption still\n  gets the minimum.\n- Maximum: 7 s (Netflix), 6 s (DCMP). Split a long one at a clause boundary.\n- Reading speed: if a caption is over the limit, extend its out-time into the gap or linger\n  first, then pull its in-time earlier (by no more than about 0.5 s), then split or trim wording\n  last. Retime before rewording.\n- Frame maths at 24 fps: 1 frame = 41.7 ms, 2 frames = 83 ms, 12 frames = 0.5 s.\n\n## Gaps\n\n- Minimum gap between two captions: 2 frames (Netflix).\n- Gaps of 3-11 frames at 24 fps: close them to 2 frames, so the caption does not blink.\n- Gaps of 12 frames or more (0.5 s) are real pauses. BBC says if you leave a pause gap it should\n  be 1 s at least, better 1.5 s, since shorter gaps look jerky.\n- Never overlap two captions in time unless they carry different speakers and the format allows\n  simultaneous cues.\n\n## Shot changes\n\nCut times come from `ae_detect_cuts` (or the editor's edit list).\n\n| Case | Rule (Netflix) |\n|---|---|\n| In-time near a cut | on the cut frame, or at least 12 frames (0.5 s) away from it |\n| Out-time near a cut | 2 frames before the cut, or at least 0.5 s after it |\n| Caption spanning a cut | acceptable when the speech spans it; otherwise snap the out-time to 2 frames before |\n\nA caption that starts 3 frames after a cut, or ends 2 frames after one, flickers against the new\nshot. Snap to the cut or move well clear of it.\n\n## Line breaks\n\n- One line if it fits. Two lines only when needed or when the speaker switches.\n- Bottom-heavy: when both lines are used, make the lower line longer, so the top one does not\n  cover the picture more than needed. Pyramids are fine; inverted ones are not.\n- Break at the highest grammatical boundary available, in this order: after a sentence end or\n  strong punctuation; before a conjunction or relative pronoun; before a preposition phrase; between\n  subject and verb phrase only if nothing better.\n- Never end a line on: an article (a, an, the), a preposition (of, to, in, on, with), a\n  conjunction (and, but, or), an auxiliary (is, was, have, will), or a subject pronoun that\n  comes before its verb (I, he, she, we, they, you).\n- Never split a first name from its surname, a number from its unit, a phrasal verb (\"give up\")\n  or a hyphenated compound.\n- Do not break the caption in the middle of a quoted title or a name of a thing.\n- The planner scores candidate breaks with `breakPenalty` / `isWeakEnd`; a violation of the\n  weak-ending rule is reported, not hidden.\n- If a break cannot be made well within the character limit, re-chunk (shorter caption) before\n  breaking badly.\n",
  },
  "motion-director": {
    "NOTICE.md": "# Sources and licences\n\nThis skill is Chroma's own synthesis, written in its own words. It adapts ideas and numbers from\nthe sources below; where they disagreed, the choice made is noted in the text (mostly by the\n\"register\" table in SKILL.md). No source text was copied verbatim. Researched 2026-11-05.\n\n| Source | Licence | Used for |\n|---|---|---|\n| [lottiefiles/motion-design-skill](https://github.com/lottiefiles/motion-design-skill) | MIT, (c) 2025 LottieFiles | duration and easing tables, archetypes, springs, Disney principles with numbers, stagger budgets, the 1/3 rules, ambient loops, severity tiers, symptom fixes |\n| [charlie947/motion-graphics-skills](https://github.com/charlie947/motion-graphics-skills) | MIT, (c) Charlie Hills | brand-first workflow, facts discipline, the 8 s move/hold/return loop, effect techniques, safe zones and hero sizes, banned defaults, one-change revisions, delivery specs |\n| [heygen-com/hyperframes](https://github.com/heygen-com/hyperframes): hyperframes-animation, hyperframes-core, general-video, motion-graphics, and the later `skills/hyperframes/references` | Apache-2.0, (c) HeyGen | ease by role, motion budget, transitions as handoffs, velocity matching and recipes, beat grid, reading time, type floors, captions, audio levels, beat shares, pacing and staleness, review loop (measure then look, contact sheets, P0-P2 notes), the \"looks generated\" list |\n| [Sunwood-ai-labs/hyperframes-motion-reel-skill](https://github.com/Sunwood-ai-labs/hyperframes-motion-reel-skill) | MIT, (c) 2026 Sunwood AI Labs | beat-grid-first timing, contrast of pace, text as image, motion-blur limits, state as a function of time |\n| [geekjourneyx/hyperframes-motion-director](https://github.com/geekjourneyx/hyperframes-motion-director) | AGPL-3.0 | **ideas only, paraphrased, nothing copied**: brief then confirm, stills before motion, layout as rectangles, vertical title tiers, hook timing gates, primitives chosen by meaning, inspectable transition midpoints, rendered-frame evidence, learning rules from defects |\n\nCaption note: an earlier draft of `references/sound-and-captions.md` followed the HyperFrames\ncaptions references too closely. That section is now rewritten in Chroma's own words and kept to\nmotion points; the caption rules moved to the separate `captions` skill, whose `NOTICE.md`\ncredits the HyperFrames caption ideas (Apache-2.0, (c) HeyGen: Whisper failure modes, word\ngrouping by energy, clean-up of words over silence) along with the other sources.\n\nChanges from the sources: rewritten for any toolchain with After Effects as the main target\n(frame conversions, bezier to AE influence and speed, chroma-ae MCP tool mapping); conflicting\nadvice reconciled by register; web-, HTML- and GSAP-specific material removed.\n",
    "SKILL.md": "---\nname: chroma-motion-director\ndescription: \"Direct and build motion pieces end to end: brief, numeric spec, still frames, choreography, sound, review and delivery, with measured timing, easing, stagger, transition, type, caption and audio rules. Use for any motion graphics, launch or promo film, social reel, explainer, title sequence, logo sting, lower third, stat or chart animation, kinetic type, or motion review, whether it is built in After Effects (through the chroma-ae MCP), Remotion, HyperFrames, Lottie or code. Also use to critique motion (\\\"it feels robotic / cheap / like slides / too fast\\\") and to turn adjectives into numbers. Trigger phrases: 'motion', 'animate', 'animation', 'promo', 'launch video', 'reel', 'sting', 'lower third', 'kinetic type', 'title sequence', 'explainer', 'easing', 'stagger', 'transition', 'make it feel premium', 'review this animation'.\"\nmetadata:\n  version: \"1.0.0\"\n  sources: see NOTICE.md\n---\n\n# Chroma motion director\n\nOne skill for directing motion, from a one-line brief to a delivered file. It merges eight\npublic skills (see `NOTICE.md`) and resolves where they disagree. The numbers are the point:\nevery rule below is meant to be measured, not admired.\n\n**Load only what the task needs:**\n\n| Task | Read |\n|---|---|\n| Any new piece | this file, then `references/spec.md` |\n| Timing, easing, springs, ms to frames, AE ease values | `references/timing-and-easing.md` |\n| Groups, stagger, cameras, transitions between scenes | `references/choreography.md` |\n| Text sizes, reading time, safe zones, layout, colour | `references/type-and-layout.md` |\n| Structure, beat shares, pacing, scene recipes | `references/story-and-pacing.md` |\n| Music, voice, sound effects, levels, captions | `references/sound-and-captions.md` |\n| Checking a piece, writing notes, the \"looks generated\" list | `references/review.md` |\n\nFor anything made for Chroma, `chroma-brand-guidelines` sets the look (palette, type, voice);\nthis skill sets the motion. In After Effects, drive the work through the `chroma-ae` MCP tools\n(`ae_motion_review`, `ae_contact_sheet`, `ae_check_legibility`, `ae_set_keyframe_ease`,\n`ae_stagger`, `ae_loudness_check` and so on) rather than raw JSX.\n\n## The process\n\nSix gates. Do not skip one because the brief is short; shrink it instead.\n\n1. **Brief, then stop.** One sentence of intent (what the viewer should feel or know at the\n   end), the audience, the format (size, fps, length, platform), the single message, the arc,\n   and what must not happen. Ask at most one clarifying question; where something is unknown,\n   write `ASK ME` rather than guess (never guess a hex colour or a fact). Show the beat sheet and\n   wait for a yes before building.\n2. **Spec: adjectives into numbers.** Write the piece's `MOTION.md` from\n   `references/spec.md`: register, signature ease, a three-tier duration palette, stagger,\n   overshoot budget, colour roles, type sizes, safe zones, the banned list, and the beat table.\n   \"Premium\" means 350-600 ms, ease (0.4, 0, 0.2, 1), no overshoot; it does not mean \"nice\".\n   A project that already has a `MOTION.md` or brand file: read it first and follow it.\n3. **Stills before motion.** Build the end state of every beat as a still and check it: one\n   hero, readable at phone size, inside the safe zones, nothing touching an edge it shouldn't.\n   Animate *from and to* those stills. A frame that fails as a still will not be saved by motion.\n4. **Choreograph.** One primary motion idea per scene, at most one supporting motion, one\n   signature moment per film. Ease by role, stagger by importance, overlap the next element when\n   the last is 30-50 % done, hand scenes off without fading out. Drive cuts and hits from one\n   beat grid when there is music.\n5. **Review: measure, then look.** Run the measured checks first (`references/review.md`), then\n   contact sheets: each beat's start and middle, a strip across every cut (−0.2 s to +0.2 s), and\n   the beat frames at phone width (360 px). Notes are `t=4.2s · where · problem → exact change ·\n   what stays`, ranked P0/P1/P2. Report only what you actually saw; say so when there is nothing.\n6. **Deliver and verify the file.** Check the rendered file, not the preview: duration, fps,\n   size, codec, colour range, loudness, frame 0 (it is the thumbnail: never black, never a lone\n   logo). State what was measured and what was only looked at.\n\n**Revisions:** one change per note. Keep the motion, timing and approved parts exactly as they\nare, and say what changed. Build exactly what was asked; offer extras instead of adding them.\n\n## Pick a register first\n\nMost conflicts between the sources disappear once the register is fixed. Pick one per piece\n(a 90/10 mix at most) and write it in the spec.\n\n| Register | Use for | Durations | Overshoot | Stagger, total | Character |\n|---|---|---|---|---|---|\n| **UI micro** | product UI in a demo, buttons, toggles, cards | 80-450 ms | 0-5 % | 20-60 ms, under 400 ms | quick, functional, no bounce on UI |\n| **Brand film** (default) | launches, promos, reels, titles, stings | moves 300-800 ms, reveals 0.8-1.6 s | 0 % premium, 3-10 % energetic | 40-120 ms, about 500 ms | arrive slow, leave clean, still when landed |\n| **Energetic** | social hooks, sport, music-led cuts | 150-400 ms | 10-25 % on position or scale only | 30-60 ms | beat-driven, hard accents, contrast of pace |\n| **Handmade** | editorial, explainer, collage, Vox-like | on twos (hold each pose 2 frames at 24 fps) | none | per element, loose | stepped, tactile, never smooth corporate easing |\n\nChroma's own work defaults to **brand film, premium**: no overshoot, no glow, no bounce,\nlanded type dead still.\n\n## Core rules (the short version)\n\n**Easing**\n- Out for arrivals, in for exits, in-out for moves between positions and for camera. Linear only\n  for rotation, progress, timers and genuinely mechanical motion.\n- Use at least three different eases in a piece; no more than two tweens with the same ease and\n  duration in a scene. Everything on one ease at 0.5 s is the clearest sign of generated motion.\n- Arrivals take long-tailed ease-outs (expo or quart out). Exits are 40-50 % shorter than\n  entrances and ease in.\n- Springs: damping ratio 0.7-0.85 reads premium, 0.4-0.6 playful, under 0.3 cartoon. Position\n  and scale may overshoot; opacity, colour and numbers never do.\n\n**Choreography**\n- One hero per moment; at most a third of a group moves at once. Dim the others to 40-60 %.\n- Stagger by importance, not by layer order: letters 1 frame apart, words 60-120 ms, list items\n  40-80 ms, and keep a group's total stagger near 500 ms so it reads as one beat.\n- Nothing travels more than a third of the frame without an intermediate key or an arc.\n- After a group resolves, leave 100-200 ms of stillness; a landed title stays dead still.\n- First move 0.1-0.3 s in, never at frame 0 of a scene unless it is a cut-in.\n\n**Transitions**\n- Hand off, don't fade out then in: the outgoing and incoming motion happen together, with the\n  ease mirrored across the seam (in on the way out, out on the way in) and the fastest frames at\n  the cut. Match direction, axis and the sign of any scale change across the cut.\n- Three to five kinds of transition per film, each with a cause on screen. One primary for\n  60-70 % of seams. At most a third are hard cuts. Never crossfade between two different worlds.\n- Every transition has a midpoint frame worth looking at. A blank midpoint is a failure.\n\n**Type**\n- Readable text is at least 2.6 % of the frame's short side (28 px at 1080). Titles 4-9 % of\n  frame height; hero words can fill 60-90 % of the width.\n- Hold a line 0.5 s + 0.3 s per word; the last line at least 2 s; at most 6 words a line.\n- Text is still before it has to be read. Animate text with a device (mask, split, scan,\n  compress, assemble, path handoff), not opacity plus a 20 px slide on everything.\n\n**Pace**\n- The hook is readable by 0.8-1.2 s; frame 0 is never empty. Something new every 2-4 s.\n  Alternate dense and still beats; the slowest scene is about three times the fastest.\n- Over 3 s with nothing changing is a dead stretch. Any single treatment goes stale after about\n  6 s.\n\n**Sound**\n- Voice leads; music sits about 14 % under it and is carved around it, not just ducked. Social\n  mixes at −16 to −14 LUFS, peaks at −1 dBTP or lower. A hit's peak lands one frame after its\n  picture. Effects only for real on-screen causes.\n\n**Content**\n- Every name, date and number on screen comes from an approved list. Sample data carries a\n  visible \"illustrative data\" label.\n- Deletion test for every element: if removing it changes nothing, remove it.\n\n## Working in After Effects\n\n- Convert ms to frames at the comp's frame rate before keying (200 ms is 6 f at 30 fps, 4.8 f\n  at 24, so round to 5 and say so). Beat frames come from the beat index, never accumulated.\n- Cubic-bezier eases become AE keyframe influence and speed: the table is in\n  `references/timing-and-easing.md`. Apply them with `ae_set_keyframe_ease`; check them with\n  `ae_motion_review` (linear keys, abrupt starts and stops, overshoot, speed jumps).\n- Seed every random (`seedRandom(n, true)` in expressions) so any frame renders the same.\n- Use `ae_contact_sheet` for the sheets in step 5, `ae_check_legibility` and `ae_measure_text`\n  for type, `ae_loudness_check` for levels, `ae_check_delivery_file` on the render.\n",
    "references/choreography.md": "# Choreography, cameras and transitions\n\n## Groups\n\n- **One hero per moment.** The hero leads, with the largest displacement. Everything else is\n  secondary or still; dim non-heroes to 40-60 % opacity when the hero needs the stage.\n- **Density:** with three or more elements, at most a third move at the same time. Two or three\n  moving things at once is the attention budget.\n- **Distance:** nothing travels more than a third of the frame without an intermediate key or an\n  arc.\n- **One origin direction** for a group. Counter-motion, when used, runs at 20-30 % of the main\n  speed.\n- **Shared trigger:** elements meant to start together start within 50 ms of each other.\n- **Overlap:** start the next element when the previous is 30-50 % done. Methodical work uses 0 %\n  overlap, brisk 25 %, fluid 50 %, rapid 75 %.\n- **Resolve:** 100-200 ms of stillness after the group lands, then the next idea.\n- **Containers first:** a shell opens before its content arrives; text waits until there is room.\n- **Shared elements travel:** a title that moves from one layout to another is the same layer\n  moving, never a duplicate fading in.\n- **Depth by speed:** foreground 1.0x, mid 0.5x, background 0.2x, far 0.1x. One vanishing point\n  for every layer.\n\n## Stagger\n\n| Kind | Delay | Total |\n|---|---|---|\n| Letters | 1 frame | |\n| Words | 60-120 ms | |\n| List items, cards, rows | 40-80 ms | |\n| Bars in a chart | 60-100 ms, fills 0.8-1.2 s | |\n| Micro (UI) | 20-40 ms | under 200 ms |\n| Standard | 50-100 ms | under 400 ms |\n| Dramatic | 100-200 ms | under 600 ms |\n\n- A group's total stagger stays near 500 ms so it reads as one beat; longer than that and it\n  reads as a list being read out.\n- Order by importance, not by layer order. Patterns: from the centre, from the edges, seeded\n  random. Same ease for the whole group; only the start times differ.\n- Path draws: stagger segments at 70-80 % of a segment's duration so the line reads as one stroke;\n  draw with linear for a pen-like trace.\n- Per-word kinetic type: the slide distance can decay per word (80, 60, 50, 25, 12 px), as if the\n  camera is settling.\n\n## Scene shape\n\nBuild 0-30 %, breathe 30-70 % (one small thing alive), resolve 70-100 %. The breathe phase is\nwhere a hold must still show one sign of life (a progress creep, a light sweep, a slow drift on\nthe background), never a title that keeps moving.\n\n**Loops** (stings, covers, GIFs): move 0-2.2 s, hold 2.2-6.6 s, return 6.6-8.0 s on an 8 s loop;\nthe last frame equals frame 0 exactly, and the return eases back rather than snapping. For a GIF,\nrotate the loop so the first frame is the finished picture. For a short B-roll cut, keep only the\nactive move (about 1.4 s) and hold the end.\n\n## Cameras\n\n- One camera, or one parent null, carries the move; the content never moves to fake a camera.\n- A camera move eases in-out (sine or quad). Phased moves (pull back, focus, push) step in scale,\n  with a very slow continuous drift so the frame is never dead still while the camera is \"on\".\n- Punch-in or Ken Burns: scale and position on a wrapper or precomp, never on the footage layer\n  itself. A still image on screen gets at least a 1.00 to 1.04 scale over its beat.\n- Rack focus: blur and dim the off-focus layers; the change runs with the push, in the same\n  window.\n- A late, slow push-in that starts after the viewer has read the frame looks generated. Push\n  while the eye is still arriving.\n\n## Transitions\n\n**Principle:** the outgoing and incoming motion happen at the same time and the motion is the\nhandoff. Do not fade out, then fade in. Only the final scene has an exit of its own.\n\n- **Velocity match:** cut at the fastest frame. The exit eases in, the entry eases out, and the\n  speeds on either side of the cut agree within about 5 %. Direction, axis and the sign of any\n  scale change match across the cut (a push stays a push).\n- **One current:** pick the film's dominant seam direction and never run two consecutive seams in\n  opposite directions.\n- **Variety with a cause:** 3-5 kinds per film, each with something on screen that causes it.\n  One primary kind for 60-70 % of seams, one or two accents. At most a third of seams are hard\n  cuts. Never crossfade between two different worlds.\n- **Placement:** the opening transition is the most distinctive (0.4-0.6 s); between related\n  points use the primary (about 0.3 s); a topic change uses a different kind; the climax is the\n  boldest and fastest; the wind-down is gentle (0.5-0.7 s); the outro is the slowest and simplest\n  (0.6-1.0 s).\n\n| Energy | Duration | Ease | Blur crossfade |\n|---|---|---|---|\n| Calm | 0.5-0.8 s | sine in-out | 20-30 px over 0.8-1.2 s |\n| Medium | 0.3-0.5 s | quad or cubic | 8-15 px over 0.4-0.6 s |\n| High | 0.15-0.3 s | quart or expo | 3-6 px over 0.2-0.3 s |\n\nPresets: instant 0.15 s · snappy 0.2 s · smooth 0.4 s · dramatic 0.5 s · gentle 0.6 s · luxe\n0.7 s.\n\n**Recipes**\n- **Whip:** exit 400 px with 24 px blur over 0.3 s on cubic in; entry from the other side with the\n  blur clearing over 0.3 s. A short smear version is 0.13-0.3 s.\n- **Zoom-through:** exit scale 1.0 to 1.2 with 10 px blur (text) or 18-20 px (full frame) over\n  0.2 s, cubic in; entry scale 0.75 to 1.0 over 0.5 s, expo out. Through a button: track to it\n  over 0.6 s, then scale 8 % to 250 % over 0.35 s on a strong ease in.\n- **Object becomes the world:** the object grows over about 0.65 s while the surroundings blur\n  15 px.\n- **Morph:** one shape becomes the next meaning over about 0.2 s, cubic out, with a horizontal\n  blur from 12 px to 0. A shape changing is premium; two pictures crossfading is cheap. Leave a\n  faint ghost of the start state when it helps the read.\n- **Cut the curve:** partial travel of about 12 % of the frame (230 px at 1920), exit quart in\n  over 0.2-0.4 s, entry quart out.\n- **Colour flood:** about 0.4 s, sine or quad in-out.\n- **Dip cut:** darken the outgoing frame about 40 % for 3 frames, then hard cut.\n- **Iris from a click:** 0.15 s.\n- **Velocity-matched blur cut:** exit 0.33 s quad in with blur to 30 px; entry 1.0 s quad out from\n  30 px.\n- Blinds: calm 4 horizontal or 6 vertical; medium 6-8 or 8; high 12-16 or 16. Avoid visible\n  repeating patterns (tiles, grids, dot arrays) as transitions; organic noise is fine.\n\n**Feedback mapping:** \"too fast\" usually means slow the zooms and pans to about 0.7x, not\neverything. \"Feels like slides\" means enter the next scene through an object already on screen.\n\n## Motion primitives by meaning\n\nChoose the device by what the moment means, not from a menu of effects:\n\n| Meaning | Device |\n|---|---|\n| Disclosure, reveal | mask or matte reveal (not opacity) |\n| A route, a process, a connection | path draw |\n| One scene replacing another | clip or shape wipe with a real midpoint |\n| A list | stagger, with a hold after it |\n| A number | count up, then lock; the number is the largest thing on screen |\n| A change of state | morph, or the same element moving |\n| Emphasis | a highlight band swept on after the text lands, or one scale pulse to about 1.12 |\n\nLines and connectors are anchored at both ends to something with a job, or replaced by a signal\non the component itself (a dot, an edge highlight, a progress strip).\n",
    "references/review.md": "# Review: measure, then look\n\nTrust the numbers over your eye, then use your eye for what numbers can't see.\n\n## 1. Measure\n\nRun these before anyone watches it. Each has a fix.\n\n| Check | Fails when | In AE (chroma-ae) |\n|---|---|---|\n| Linear spatial keys | position, scale or rotation of a non-mechanical element moves at constant speed | `ae_motion_review` |\n| Abrupt start or stop | speed jumps from or to zero without an ease | `ae_motion_review` |\n| One ease everywhere | more than two tweens in a scene share the same ease and duration | `ae_get_keyframes` across layers |\n| Wrong direction | an entrance eases in, or an exit eases out | `ae_get_keyframes` |\n| Overshoot where it shouldn't | opacity, colour or a counting number overshoots | `ae_motion_review` |\n| Exit too long | an exit is not 40-50 % shorter than its entrance | keyframe spans |\n| Stagger | sibling start offsets outside the table, or the group spread far over 500 ms | `ae_stagger` plan / keyframe starts |\n| Density | more than a third of a group moving at once | keyframe overlap |\n| First move at 0 | a scene's first move starts on its first frame | keyframe starts |\n| Unread line | a text layer is on screen for less than 0.5 s + 0.3 s per word | text layer in/out and word count |\n| Text below the floor | text under 2.6 % of the short side at its smallest on-screen scale | `ae_check_legibility`, `ae_measure_text` |\n| Outside safe zones | text or logo outside title-safe or the platform's bands | `ae_check_legibility`, `ae_house_style_check` |\n| Overlap | text overlapping text or the subject | `ae_check_text_overlap` |\n| Dead stretch | over 3 s with nothing changing | per-frame change across the timeline |\n| First frame empty | frame 0 is black, empty or a lone logo | `ae_snapshot_frame` at 0 |\n| Silent film | over 15 s with no sound | `ae_audio_analyze` |\n| Loudness | outside −16 to −14 LUFS or peaks over −1 dBTP | `ae_loudness_check` |\n| Loop seam | the last frame of a loop differs from frame 0 | `ae_compare_frames` |\n| Nothing moves | the biggest change against frame 0 is near zero in a \"motion\" piece | `ae_compare_frames` |\n| Late or out of order | an element appears after its intended time, or before one it should follow | markers against layer in-points |\n| Facts | a name or number on screen isn't on the approved list | text layers against the list |\n| Delivery | duration, fps, size, codec, colour range or audio streams differ from the spec | `ae_check_delivery_file`, `ae_verify_render` |\n\n## 2. Look\n\nThree contact sheets:\n\n1. **Beats:** each scene just after it starts, at its middle, and at every beat or hit.\n2. **Seams:** a strip across every cut, from −0.2 s to +0.2 s. Look for a jump in position,\n   scale or colour at the seam, a speed mismatch, and a blank midpoint.\n3. **Phone:** the beat frames at 360 px wide, with the sound off.\n\nDescribe each beat frame as a stranger would, in one sentence. Ask: does it read as what it is?\nDoes the subject separate from the background? Is anything you'd have to explain? Would the\npictures alone tell the story? Then the screenshot test: a good motion piece loses meaning when\nreduced to stills; slides don't.\n\nUse the rendered file for this, not the preview: the two can differ. Pull the same frames from\nthe render and compare them.\n\n## 3. Write notes\n\nOne line each:\n\n```\nt=4.2s · headline · lands then keeps scaling → stop the scale key at 4.0s · keep the ease and timing\n```\n\nRank them **P0** (breaks the read), **P1** (weakens it), **P2** (polish). Don't score out of 10.\nReport only what you actually saw; if there is nothing, say so. If the film feels busy, remove a\nthird of the motion before adding anything.\n\nOptionally ask a fresh agent to critique from only the brief and the sheets, without seeing the\nbuild, then compare.\n\nEnd with a short delivery note: the calls made, what was measured and what was only looked at,\nthe weakest shot, and any warnings deliberately kept and why. Every \"pass\" names the frame and\ntime it was checked on.\n\n## 4. Learn\n\nEach defect found late gets a cause and a rule: add it to the project's `MOTION.md` banned list\nor to the checks above, so it is caught earlier next time. The AE MCP's `ae_learn_taste` and\n`ae_taste_rules` keep these per project.\n\n## Looks generated\n\nThe tells. Any of these in a piece needs a reason.\n\n- Everything fades and slides up; every scene enters the same way; the same ease at 0.5 s on\n  everything.\n- Titles that keep drifting, breathing or scaling after they land; floating or pulsing loops on\n  titles or UI as fake life.\n- Bounce on UI; click rings; typewriter headlines (typing belongs inside an input box); glow and\n  bloom as decoration; gradients on text.\n- A dark void with small centred things; purple-to-blue backgrounds; glass cards; three cards in a\n  row; grids of KPI tiles; HUD corners; a logo docked in a corner.\n- Grey placeholder bars, stock icons, emoji, clip art, rockets and sparkles.\n- A late, slow push-in after the frame has been read.\n- Crossfades between unrelated worlds; a fade out then a fade in at every cut.\n- A pie chart, a legend, gridlines.\n\n## Symptoms to fixes\n\n| It feels | Try |\n|---|---|\n| Robotic | ease every spatial key, add arcs, offset starts by 50-150 ms |\n| Cheap or flat | a secondary layer, follow-through, 3-10 % overshoot on position or scale (not in premium) |\n| Too slow | shorten holds before shortening moves; check the duration tier for the register |\n| Too fast | slow the zooms and pans to about 0.7x, leave the rest |\n| Like slides | enter each scene through an object already on screen; vary the entrances |\n| Busy or distracting | one hero per moment; remove a third of the motion |\n| No personality | pick a register and a signature ease and use it for 80 % of moves |\n| Inconsistent | one duration palette, one entrance pattern, the same ease family per group |\n",
    "references/sound-and-captions.md": "# Sound and captions\n\n## Voice\n\n- Narration runs 2.2-2.5 words a second. A scene of about 9 s carries about 19 words, 26 at most.\n  A 30-90 s piece is about 155 words or fewer.\n- Script first, then real timings: the recorded (or synthesised) voice's word timestamps set the\n  scene boundaries, not the written estimate. If the voice runs longer than the picture, trim the\n  script; never stretch the motion to fill.\n- Write numbers as they are spoken.\n\n## Music and effects\n\n- Voice leads. Music under voice sits at about 14 % volume and is **carved** (an EQ dip where the\n  voice lives, around 1-4 kHz), not just ducked. Drop the score entirely while the voice must be\n  heard clearly.\n- Music enters on its strongest bar and ends on a bar line with a short fade. Looping beds: 0.4 s\n  fade in, 1.5 s fade out. Anything over 15 s that tells a story gets a bed plus effects.\n- Effects only for real causes on screen: a click, a whoosh on a cut, a key tick, a pop, one\n  riser into the payoff. Each hit sits 3-6 dB above the bed. Rotate two or three takes of a\n  repeated sound.\n- Timing: a sound's peak lands one frame after its picture. A move that lands on a hit starts\n  40-190 ms early; a reaction starts 0-45 ms after it.\n- A bed whose energy is mostly under 150 Hz disappears on phone speakers.\n- A generated score is possible in code (low bed, a hit per shot, a lift at the end): kick as a\n  falling sine, hats as filtered noise, an impact as sub plus noise with a short decay.\n- Audio-reactive motion stays micro: text and logos pulse at most 5 % in scale, backgrounds\n  10-30 %. No equaliser bars, no strobing.\n- Never claim a beat analysis that did not happen; a hand-made beat map is fine if it says so.\n\n## Levels\n\n| Target | Value |\n|---|---|\n| Social and web mix | −16 to −14 LUFS integrated |\n| True peak | −1 dBTP or lower |\n| Speech level in a clean recording | roughly −26 to −16 dB |\n| Broadcast | the platform's spec (EBU R128 −23 LUFS, ATSC A/85 −24 LKFS) |\n\nEQ starting points: high-pass at 80 Hz for rumble; reduce mud at 250 Hz, −3 dB, Q 1.2; reduce\nboxiness at 400 Hz, −3 dB; clarity at 3 kHz, +2.5 dB; soften harshness at 3.2 kHz, −3 dB.\nSubtract before adding; the limiter goes last.\n\n## Captions\n\nThe caption rules (standards, reading speed, line breaks, speakers, file formats, tools) live in\nthe `captions` skill. This section covers only how captions meet the motion.\n\n- Time a caption to the speech, then check it against the beat grid: a caption change that lands\n  within a few frames of a cut or a hit looks planned; one that lands just off it looks like a\n  mistake. Move the caption, not the cut.\n- Keep captions out of the action: not over the speaker's mouth or eyes, the hero, or the\n  platform UI. Give them one fixed home so the eye learns where to look.\n- Caption motion is quiet. A fade or a short rise of 100-150 ms is enough; save big moves for\n  the hero. A word highlight starts a frame or two early.\n- One caption style per film: same font, size, colour roles and box. Change it only with the\n  scene, and on purpose.\n- Over footage with a busy background, use a backing box (60% black or more) before reaching for\n  blend modes.\n- Check captions in the silent pass: the film should work with the sound off.\n\n## Review with and without sound\n\nThree passes: **silent** (can the story be followed with the sound off, at phone size?),\n**audio** (do the hits land on their causes?), **frame** (is each hit frame readable as a\nstill?). Say which of these were measured and which were only judged by eye or ear; a loudness\nreading is a measurement, \"the mix sounds fine\" is not.\n",
    "references/spec.md": "# The spec: MOTION.md\n\nEvery piece gets a `MOTION.md` beside its project (in AE projects, next to the `.aep`). It turns\nthe brief's adjectives into numbers, and it is what the review checks against. Read an existing\none before touching the piece; if the brand has one, copy it in and only add the piece's beats.\n\nFill every field. Where the answer is unknown, write `ASK ME`; never invent a colour or a fact.\n\n```markdown\n# MOTION.md: <piece name>\n\n## Goal\nOne sentence: what the viewer feels or knows at the end.\nAudience: ...   Platform: ...   Sound: on / off by default\n\n## Format\nSize: 1920x1080 | 1080x1920 | 1080x1350 | 1080x1080     Fps: 24 | 25 | 30 | 60\nLength: ... s    Music: ... BPM (or none)    Safe zones: see type-and-layout.md for the format\n\n## Register\nbrand film / premium     (UI micro | brand film | energetic | handmade; at most a 90/10 mix)\n\n## Motion language\nSignature ease: (0.4, 0, 0.2, 1)  for about 80 % of moves\nArrival ease: expo out    Exit ease: cubic in, 40-50 % shorter than entrances\nCamera ease: sine in-out\nDurations: short 300 ms / medium 500 ms / long 800 ms   (in frames: ... / ... / ...)\nStagger: words 80 ms, items 60 ms, group total about 500 ms\nOvershoot: 0 % (position and scale only, never opacity, colour or numbers)\nEntrance pattern: mask reveal from below\nTransitions: primary = <kind> for most seams; accents = <kind>, <kind>; hard cuts at most 1/3\nMotion blur: fast moves only\n\n## Look\nColours (hex, with a role each): background ..., text ..., accent ..., data ...\nType: display <font> <weight>, body <font> <weight>; title ... px, body ... px, floor 2.6 % of short side\nTexture: grain / none     Background: never flat #000\n\n## Facts\nThe approved names, dates and numbers. Nothing else appears on screen.\nSample data: labelled \"illustrative data\" on every frame it appears.\n\n## Banned\nFive things this piece must never do (start from review.md \"Looks generated\").\n\n## Beats\n| # | Time (s or beats) | Role | On screen | Hero frame at | Enter / lock / exit / bridge | Sound |\n|---|---|---|---|---|---|---|\n| 1 | 0-1.2 | hook | ... | 0.8 | ... | hit at 0.8 |\n\n## Checks\nThe measured checks in review.md that apply, and any extra ones for this piece.\n```\n\n## Brand defaults\n\nFor Chroma's own pieces, the register is brand film, premium: signature ease (0.4, 0, 0.2, 1),\nno overshoot, no glow or bounce, type still once landed, colours and fonts from\n`chroma-brand-guidelines`, and the brand's spectrum used once per piece.\n",
    "references/story-and-pacing.md": "# Story, structure and pacing\n\n## The brief\n\nBefore anything is built, the brief answers:\n\n- **Intent:** what the viewer feels or knows at the end, in one sentence.\n- **Essence:** the core point, the main tension, the emotional centre, the one word to amplify,\n  one visual metaphor.\n- **Format:** size, fps, length, platform, safe zones, sound on or off by default.\n- **Facts:** the approved list of names, dates and numbers that may appear.\n- **Arc** (below), **risks**, and **what must not happen**.\n\nThen a beat sheet: for each beat its time range, on-screen text, the hero-frame time (the frame\nthat has to work as a still), how text enters, locks, is emphasised, exits and bridges to the\nnext beat, and what would be lost if the motion were removed. Show it and wait for approval.\n\nTreat a short prompt as a seed: expand it into a world, a story, keywords, colour, type, shapes,\ncamera and sound, but anything the user specified wins. Don't settle on the safe option.\n\n## Arcs\n\n| Length | Arc |\n|---|---|\n| 10 s | hook, tension, reveal, CTA |\n| 15 s | hook, tension, reveal, proof, CTA |\n| 30 s | pattern interrupt, conflict, reveal, proof, outcome, CTA |\n| Launch, 20-45 s | hook 8 %, tension 12 %, reveal 8 % (placed 20-30 % in), proof 40 %, payoff 20 % (placed 60-80 % in), claim 8 %, end card 8 % (holds 2-3 s) |\n\nNarrative roles for scenes: hook, problem, product intro, key feature, benefits, social proof,\nCTA, brand outro. A product promo climbs a ladder: pain, mechanism, proof, confidence, CTA.\n\n**Reference durations:**\n- 15 s promo: hook 0-3 s, proof 3-11 s at about 2.5 s a point, end card 11-15 s.\n- 45 s launch: 0-4, 4-9, 9-17, 17-22, 22-32, 32-38, 38-45 s; the CTA holds at least 3 s.\n- Apple-style product film: 6-8 scenes of about 2.5 s.\n- Explainer: 8-14 shots, one sentence each; the question shown big and a first surprise within\n  5 s.\n\n## Pacing\n\n- **Hook:** the first readable thing by 0.8-1.2 s (about 0.5 s for an unnarrated sting). The\n  first 0-2 s name the first place the eye goes, the largest word or object, and a motion event\n  that stops the scroll. The first 2 s are the densest. Frame 0 is the thumbnail: never black,\n  never a lone logo.\n- **Rhythm:** shots average 1.8-3 s; montage cuts 0.13-0.8 s; a product demo holds one framing\n  7-10 s; vertical shots 1-2 s with a new beat every 2-4 s. Hold 0.3-0.75 s before a payoff.\n- **Contrast of pace:** fast, stop, explode; dense, release. Alternate high-motion and still\n  beats, and don't give every beat the same length. The slowest scene is about three times the\n  fastest.\n- **Staleness:** something new every 2-4 s. Over 3 s with nothing changing is a dead stretch. A\n  static card dies after about 8 s (stage a reveal inside anything over 15 s). Any single\n  treatment goes stale after about 6 s. Over a talking head, one card every 6-8 s (under a\n  minute), 8-12 s (up to 3 min), 12-20 s (up to 10 min).\n- **Pattern interrupt:** past about 2.5 s, change exactly one thing.\n- **Holds:** title 0.6-1.2 s after it lands · proof or stat 0.8-1.5 s · CTA at least 1 s and the\n  calmest hold in the film · after-state of a transformation at least 1.2 s.\n- **Music-led:** every cut, impact, title entrance and camera switch sits on a beat, half beat or\n  quarter beat. Write times in beats, not seconds.\n\n## Scene recipes\n\n- **Stat:** the count runs 1.2-1.6 s on a decelerating ease, then holds; a ring or bar finishes\n  with the count; the label appears after the number lands (value, then meaning). About 4-6 s in\n  all. No overshoot.\n- **Logo reveal:** 3-5 s. Vector logos draw on; raster logos reveal through a mask or a scale.\n  An underline or light sweep, then hold. Export with alpha for stings.\n- **Lower third:** 3-6 s. A bar wipes in from the left (scale X 0 to 100 %), the text slides up\n  behind it, hold, then slide out. Bottom 30 %, title-safe, alpha.\n- **Highlight a phrase:** the sentence slides up 52 px over 0.8 s (quart out), and after it has\n  settled a highlight band sweeps left to right over 0.5-1.5 s scaled to the phrase length. The\n  text is never zoomed to emphasise it.\n- **Title card (the breather):** one move, then a still hold of 3-5 s.\n- **Kinetic beat slam:** one beat list drives every entrance; each phrase gets its own entrance\n  (scale slam, side snap, rise and rotate), never the same punch-in reused; hits 0.35-0.6 s,\n  exits 0.25 s or less; end on a locked final frame.\n- **Press and success:** container scale 0.9 to 1.0 with 5-10 % overshoot over 200 ms, a tick\n  drawn over 150 ms starting 100 ms later, 400-500 ms in all.\n- **Loading or dashboard build:** skeleton at 0, hero at 100-250 ms, widgets from 200 ms at 60 ms\n  apart, chart at 350 ms, all landed by 500 ms, ambient from 650 ms.\n\n## Variants and references\n\n- Build the first 10 s in two or three styles and choose before building the rest.\n- Breaking down a reference in five lines: pace, what changes, type, colour and light, the one\n  idea. Take moves from a reference video and the look from a still; never copy a logo, copy or\n  palette. Note the exact source, at least three observed visual properties and what must not\n  drift from the story.\n",
    "references/timing-and-easing.md": "# Timing and easing\n\n## Durations\n\n**By element (UI register):** tooltip 80-120 ms · button or toggle 120-180 ms · icon\n150-250 ms · card 200-350 ms · modal 300-400 ms · page 400-600 ms · dramatic reveal\n600-1200 ms · ambient loop 2-20 s. Hover under 100 ms, press under 150 ms, settle 200-300 ms,\nerror shake 300-400 ms with 2-3 swings of ±10-15 px.\n\n**By speed tier (film register):** fast 0.15-0.3 s (energy) · medium 0.3-0.5 s · slow\n0.5-0.8 s (luxury) · very slow 0.8-2.0 s (cinematic). A fast move across the frame is\n0.3-0.6 s. A premium reveal is 0.8-1.6 s. A tween over 2.0 s is usually too slow unless it is a\ncamera drift or an ambient loop.\n\n**By distance:** scale the base duration by 0.8x at 50 px, 1.0x at 100 px, 1.3x at 200 px,\n1.6x at 400 px, 1.8-2.0x across the full frame.\n\n**By material:** rigid 1.2x and no overshoot · elastic 0.8x and 15-25 % · fluid 1.5x and 5 % ·\npaper 1.0x and 3-5 % · gas 2.0x and none · glass 0.9x and none.\n\n**Exits** are 40-50 % shorter than the entrance (0.4 s in, 0.25 s out) and ease in. **Landing\nis longer than leaving.** If entrances feel snappy to the point of glitching, slow the whole\npiece by about 1 s before tuning single moves.\n\n## Brand identity in three constants\n\nA piece (or a brand) has one **signature ease** used for about 80 % of moves, a **three-tier\nduration palette** (for example 200 / 300 / 450 ms) and **one entrance pattern**. Everything else\nis an accent. Write all three in the spec.\n\n| Archetype | Durations | Signature ease | Overshoot |\n|---|---|---|---|\n| Premium | 350-600 ms | (0.4, 0, 0.2, 1) | 0 % |\n| Corporate | 200-400 ms | (0.2, 0, 0, 1) | 0-3 % |\n| Playful | 150-300 ms | back out | 10-20 % |\n| Energetic | 100-250 ms | expo out | 15-30 % |\n\n## Ease by role\n\n| Role | Ease | Bezier |\n|---|---|---|\n| Arrival, hero or title | expo out / quart out | (0.16, 1, 0.3, 1) / (0.25, 1, 0.5, 1) |\n| Ordinary arrival | quad or cubic out | (0.2, 0, 0, 1) |\n| Exit | cubic in | (0.3, 0, 1, 1) |\n| Move between positions | cubic in-out | (0.65, 0, 0.35, 1) |\n| Camera, colour flood, crossfade | sine or quad in-out | (0.37, 0, 0.63, 1) |\n| Zoom-through, push into a cut | cubic in, strong | (0.5, 0, 0.75, 0) |\n| Ambient loop | sine in-out | (0.37, 0, 0.63, 1) |\n| Typing, counters, stepped looks | hold keys / steps | n/a |\n| Rotation, progress, timers | linear | (0, 0, 1, 1) |\n\nNamed presets worth keeping: Material standard (0.2, 0, 0, 1), emphasised (0.05, 0.7, 0.1, 1),\ndecelerate (0, 0, 0, 1), accelerate (0.3, 0, 1, 1); Apple (0.25, 0.1, 0.25, 1); gentle float\n(0.4, 0, 0.2, 1).\n\n**Emotion to motion:** joy, back out at 200-400 ms · calm, sine at 500-1000 ms · urgency, ease\nout at 100-200 ms · sadness, cubic in-out at 600-1200 ms · surprise, expo out at 150-300 ms ·\nelegance, (0.4, 0, 0.2, 1) at 400-700 ms. Angular paths read tense, curved friendly, rising\ngrowth, horizontal progress.\n\n## Springs and overshoot\n\n- Damping ratio 1.0 never bounces · 0.7-0.85 premium · 0.4-0.6 playful · under 0.3 cartoon.\n- Back-out strength: 1.2 elegant · 1.7-2.0 the usual pop · 2.5 playful.\n- Overshoot budget by context: success 5-10 % · feedback 2-5 % · celebration 15-25 % · error 0 %\n  · premium 0 %.\n- Only position and scale may overshoot. Opacity, colour and counting numbers never do (an\n  overshooting number reads as wrong data).\n- Press and release: scale 0.88 / 0.92 / 0.96 (dramatic / default / subtle), never below 0.85 or\n  above 0.98; press straight in, release on a spring.\n\n## Classic principles, with numbers\n\n- **Anticipation:** 100-200 ms at 10-20 % of the move, opposite direction. Skip it on moves\n  under 150 ms.\n- **Squash and stretch:** squash [1.2, 0.8], stretch [0.85, 1.15]; impact 2-4 frames, recovery\n  4-8 frames. Keep volume roughly constant.\n- **Follow-through:** children lag 50-150 ms; trailing parts stop 100-200 ms after the lead.\n- **Arcs:** push the path midpoint 10-20 px off the straight line.\n- **Exaggeration:** playful 15-25 % · energetic 20-30 % · corporate 0-5 % · premium 0 %.\n- **Layers of motion:** primary at 100 % amplitude; secondary at 30-50 %, 50-100 ms later, on a\n  different ease; ambient at 10-20 % (only on backgrounds, never on titles or UI).\n\n## Ambient (backgrounds only)\n\nBreathing scale 0.98-1.02 over 2-4 s (beyond ±5 % it demands attention) · float ±5-15 px over\n3-5 s, with layered periods such as 3.5 / 4.0 / 5.5 s so elements never sync · gradient shift\n8-20 s · shimmer sweep 1.5-2.5 s with 2-5 s between sweeps · slow background orbit 3-5° a\nsecond · fewer than 20 particles · ambient energy at most 20 % of the primary motion.\n\n## Motion blur\n\nOnly on fast, short moves (slams, whips, scale punches). Blur peaks at the fastest frame and\nreaches 0 at the settle, on the same ease and window as the move: 6-12 px on text-sized\nelements, 15-20 px full-frame, horizontal-only on a horizontal move. Never on text being read,\nslow moves or fades.\n\n## Milliseconds to frames\n\n| ms | 24 fps | 25 fps | 30 fps | 60 fps |\n|---|---|---|---|---|\n| 100 | 2.4 → 2 | 2.5 → 3 | 3 | 6 |\n| 150 | 3.6 → 4 | 3.75 → 4 | 4.5 → 5 | 9 |\n| 200 | 4.8 → 5 | 5 | 6 | 12 |\n| 250 | 6 | 6.25 → 6 | 7.5 → 8 | 15 |\n| 300 | 7.2 → 7 | 7.5 → 8 | 9 | 18 |\n| 400 | 9.6 → 10 | 10 | 12 | 24 |\n| 500 | 12 | 12.5 → 13 | 15 | 30 |\n| 800 | 19.2 → 19 | 20 | 24 | 48 |\n| 1000 | 24 | 25 | 30 | 60 |\n\nRound to whole frames and keep keys on whole frames (sub-frame keys render unpredictably).\nUnder 24 fps a 100 ms move is two frames and reads as a cut; give it at least three.\n\n**Beat grid:** frames per beat = fps × 60 / BPM. Compute beat *n* as `round(n × fps × 60 / BPM)`,\nnever by adding a rounded beat repeatedly: at 128 BPM and 30 fps that drifts 2 frames in 32\nbeats. Cut on the beat, change layout on the bar.\n\n## Cubic-bezier to After Effects keyframe ease\n\nA bezier (x1, y1, x2, y2) between key A and key B, with the value changing by Δ over duration D\n(so the average speed is Δ / D):\n\n- **A, outgoing:** influence = x1 × 100 %, speed = (y1 / x1) × Δ / D.\n- **B, incoming:** influence = (1 − x2) × 100 %, speed = ((1 − y2) / (1 − x2)) × Δ / D.\n\nAE influence must be between 0.1 % and 100 %. A bezier with y outside 0-1 (back, elastic) has no\ntwo-key equivalent: add an overshoot key (for example 105 % at 70 % of the time, then settle) or\nuse a spring expression.\n\n| Ease | A out (influence / speed) | B in (influence / speed) |\n|---|---|---|\n| AE Easy Ease | 33.33 % / 0 | 33.33 % / 0 |\n| (0.2, 0, 0, 1) standard | 20 % / 0 | 100 % / 0 |\n| (0.4, 0, 0.2, 1) premium | 40 % / 0 | 80 % / 0 |\n| (0.16, 1, 0.3, 1) expo out | 16 % / 6.25 × avg | 70 % / 0 |\n| (0.25, 1, 0.5, 1) quart out | 25 % / 4 × avg | 50 % / 0 |\n| (0.3, 0, 1, 1) exit | 30 % / 0 | 0.1 % / 2-3 × avg (it leaves at speed; match the next shot's entry speed) |\n| (0.65, 0, 0.35, 1) in-out | 65 % / 0 | 65 % / 0 |\n\nFor multi-dimensional spatial properties, apply the ease to the speed graph (the whole move),\nnot per axis, unless the dimensions are separated.\n",
    "references/type-and-layout.md": "# Type, layout and colour\n\n## Sizes\n\n**Floor:** readable text is at least 2.6 % of the frame's short side: 28 px at 1080, 50 px at\n1920 wide in a vertical. Check every text layer at its smallest scale on screen.\n\n| Role | Landscape 1920x1080 | Notes |\n|---|---|---|\n| Hero word | fills 60-90 % of the width | 1-2 words |\n| Title | 4-9 % of frame height (64-120 px) | at most 6 words a line |\n| Quiet line, subtitle | 2.5-4 % of height | |\n| Body | 28-42 px | 1-2 lines |\n| Label | 18-24 px only if it is not meant to be read; otherwise 28 px+ | |\n\n- Portrait type is landscape × 1.3 (titles × 1.35, stats × 1.4).\n- Social feed headlines 90 px or more on 1080 wide; full-screen viewing headlines 60 px+, body\n  20 px+ is the absolute floor and only for viewing at full size.\n- Vertical title tiers by line length (1080x1920): 1 short line 118-156 px, line height\n  0.95-1.05 · a longer single line 96-118 px · two short lines 78-96 px · two longer lines\n  62-78 px · three lines or legal copy 48-62 px. Support text 30-44 px, CTA 28-40 px. 24-48 px\n  between title and support, 40-72 px between support and CTA, at least 72 px from a text block to\n  the edge of its field.\n- Tracking at display sizes −0.03 to −0.05 em. Weight contrast 300 against 900, not 400 against\n  700. Light text on dark: body weight about 350 and line height 0.05-0.1 more.\n- Numbers that count use tabular figures and round to the displayed precision.\n- Never let the text box be wider than the frame allows: fit it (`ae_fit_text`), don't rely on\n  manual line breaks in body copy.\n\n## Reading time\n\n- Hold a line 0.5 s + 0.3 s per word. The last line holds at least 2 s. A one- or two-word chapter\n  line can hold 0.4 s. A key element stays readable at least 0.3 s even in a montage.\n- A typographer's check: 3 s on screen must be readable in 2.\n- One line on screen at a time for titles (explainers can run to about 10 words).\n- Text is still before it has to be read. A landed title does not drift, breathe or scale.\n- Exit with a 0.13-0.25 s blur-out or a mirrored move, not a long fade.\n\n## Copy on screen\n\n- One idea per beat. Short, strong words; at most about five words on screen for social.\n- Kinetic type: 3-7 words a scene, 1-2 emphasis words, scenes tagged hook, build, punch, resolve.\n- On-screen text is shorter than the voiceover saying it.\n- Avoid launch clichés in copy: \"introducing\", \"meet\", \"unlock\", \"seamless\", \"supercharge\".\n\n## Safe zones\n\n| Format | Keep text and logos |\n|---|---|\n| Any | inside an 80 % title-safe box (10 % in from each edge) |\n| 16:9 captions | 80-120 px above the bottom |\n| 9:16 reels and shorts (1080x1920) | safe on TikTok, Reels and Shorts: x 120-888, y 288-1248 (approximate, from ad specs; per-app zones in the `captions` skill); below y 840 keep clear of the right rail (end text by x 780); headline around y 360-520 |\n| 9:16 promo layout | CTA, subtitles and proof above the bottom 15 %; the main title above the bottom 22 %; avoid the top 8-10 % |\n| Lower third | inside the bottom 30 %, inside title-safe |\n| Picture-in-picture | inset 28 px from the edges |\n\nBelow y 1248 on a vertical, only texture.\n\n## Layout\n\n- The hero of a shot fills at least 40 % of frame height or width (60-70 % for a single-object\n  shot). Small objects floating in empty space look like a template.\n- At least three layers per scene: background, content, accents. Two focal points at most. Anchor\n  things to edges rather than centring everything.\n- Write the layout as rectangles before building: text box, subject box, quiet zone, safe bottom,\n  motion bounds. A vertical text side often takes 42-48 % of the width as a quiet zone with the\n  subject opposite it, or the subject in the central 60 %.\n- Three or more beats with the same text box, the same entrance and the same rhythm look like\n  slides; change one of them.\n- Hook frames on short vertical pieces put the text impact in the centre or upper centre; keep\n  the lower half for CTA, proof and subject.\n- Overshooting or pulsing elements need clearance at their largest size.\n- Data: one number at a time, the biggest thing on screen, with a proportional visual (bar, ring).\n  Related stats share one visual space; only the value changes. Build a chart in reading order:\n  axis, reference line, data drawing in, one annotation. Highlight one series and grey the rest.\n  Avoid pie charts, dual axes, legends, gridlines and dashboards of six or more panels. Values\n  never change during a morph between chart types. Lines are drawn, not faded in.\n\n## Colour\n\n- Never a flat #000 background, and no full-screen linear gradients on dark: they band in H.264.\n  Use a solid with a glow, or a radial.\n- Atmosphere sits at 15-25 % opacity; 5 % vanishes after compression. Focal elements at full\n  saturation. Tint the neutrals.\n- Contrast for text meets WCAG AA (4.5:1 body, 3:1 large).\n- Move into the \"success\" colour rather than starting there; flash an error colour, then settle.\n- Over footage, pick the text blend by the brightness behind it: under 60 (of 255) screen, 60-180\n  overlay, over 180 normal with an opaque colour. Plain subtitles over anything brighter than 60\n  get a 30-40 % scrim sized to the text, never a full-width bar.\n",
  },
};

